   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Constitución Española (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('iipp-a02-poder-judicial-tc-fiscal', 'Primera parte, tema 2. El Poder Judicial, el CGPJ, el Tribunal Constitucional y el Ministerio Fiscal') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-a02-poder-judicial-tc-fiscal' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"El Poder Judicial: principios (art. 117 CE)"},{"n":"2","title":"El Consejo General del Poder Judicial (art. 122 CE)"},{"n":"3","title":"Organización jurisdiccional (art. 26 LOPJ)"},{"n":"4","title":"El Ministerio Fiscal (art. 124 CE)"},{"n":"5","title":"El Tribunal Constitucional: composición (arts. 159-160 CE)"},{"n":"6","title":"Competencias, legitimación y sentencias del TC (arts. 161-164 CE)"}]'::jsonb, '["Art. 117.1 CE: «La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial»","Art. 117.1 CE: «independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.»","Art. 117.2 CE: «Los Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados, sino por alguna de las causas y con las garantías previstas en la ley.»","Art. 117.3 CE: «corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes»","Art. 122.2 CE: «El Consejo General del Poder Judicial es el órgano de gobierno del mismo.»","Art. 122.3 CE: «y por veinte miembros nombrados por el Rey por un período de cinco años.»","Art. 122.3 CE: «De éstos, doce entre Jueces y Magistrados de todas las categorías judiciales»","Art. 124.1 CE: «tiene por misión promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley»","Art. 124.2 CE: «El Ministerio Fiscal ejerce sus funciones por medio de órganos propios conforme a los principios de unidad de actuación y dependencia jerárquica»","Art. 124.4 CE: «El Fiscal General del Estado será nombrado por el Rey, a propuesta del Gobierno, oído el Consejo General del Poder Judicial.»","Art. 159.1 CE: «El Tribunal Constitucional se compone de 12 miembros nombrados por el Rey»","Art. 159.1 CE: «dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial.»","Art. 159.2 CE: «todos ellos juristas de reconocida competencia con más de quince años de ejercicio profesional.»","Art. 160 CE: «a propuesta del mismo Tribunal en pleno y por un período de tres años.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"El Poder Judicial: principios constitucionales","blocks":[{"text":"El Título VI de la Constitución arranca con una idea clave: la justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial. La propia Constitución les atribuye cuatro notas: son independientes, inamovibles, responsables y están sometidos únicamente al imperio de la ley (la LOPJ añade «a la Constitución»).","refs":[{"ref":"Art. 117.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La justicia emana del pueblo y se administra en nombre del Rey por Jueces y Magistrados integrantes del poder judicial, independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley."},{"ref":"Art. 1 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"sometidos únicamente a la Constitución y al imperio de la ley."}]},{"text":"La inamovilidad significa que no pueden ser separados, suspendidos, trasladados ni jubilados sino por las causas y con las garantías previstas en la ley. El ejercicio de la potestad jurisdiccional, juzgando y haciendo ejecutar lo juzgado, corresponde en exclusiva a los Juzgados y Tribunales determinados por las leyes, que no ejercen más funciones que esa y las que la ley les atribuya en garantía de cualquier derecho.","refs":[{"ref":"Art. 117.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los Jueces y Magistrados no podrán ser separados, suspendidos, trasladados ni jubilados, sino por alguna de las causas y con las garantías previstas en la ley."},{"ref":"Art. 117.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El ejercicio de la potestad jurisdiccional en todo tipo de procesos, juzgando y haciendo ejecutar lo juzgado, corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes"}]},{"text":"El principio de unidad jurisdiccional es la base de la organización de los Tribunales; la jurisdicción militar queda reducida al ámbito estrictamente castrense y al estado de sitio, y se prohíben los Tribunales de excepción.","refs":[{"ref":"Art. 117.5 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El principio de unidad jurisdiccional es la base de la organización y funcionamiento de los Tribunales."},{"ref":"Art. 117.6 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Se prohíben los Tribunales de excepción."}]}]},{"n":"2","title":"Otras reglas constitucionales sobre la Justicia","blocks":[{"text":"Es obligado cumplir las sentencias y resoluciones firmes y colaborar con jueces y tribunales en el proceso y en la ejecución. La justicia es gratuita cuando lo disponga la ley y, en todo caso, para quienes acrediten insuficiencia de recursos para litigar. Los daños por error judicial o por funcionamiento anormal de la Administración de Justicia se indemnizan a cargo del Estado.","refs":[{"ref":"Art. 118 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Es obligado cumplir las sentencias y demás resoluciones firmes de los Jueces y Tribunales, así como prestar la colaboración requerida por éstos en el curso del proceso y en la ejecución de lo resuelto."},{"ref":"Art. 119 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La justicia será gratuita cuando así lo disponga la ley y, en todo caso, respecto de quienes acrediten insuficiencia de recursos para litigar."},{"ref":"Art. 121 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los daños causados por error judicial, así como los que sean consecuencia del funcionamiento anormal de la Administración de Justicia, darán derecho a una indemnización a cargo del Estado, conforme a la ley."}]},{"text":"Los ciudadanos participan en la Justicia mediante la acción popular y el Jurado. La policía judicial depende de Jueces, Tribunales y Ministerio Fiscal en la averiguación del delito y el aseguramiento del delincuente. Jueces, Magistrados y Fiscales en activo no pueden desempeñar otros cargos públicos ni pertenecer a partidos políticos o sindicatos, aunque sí a asociaciones profesionales.","refs":[{"ref":"Art. 125 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los ciudadanos podrán ejercer la acción popular y participar en la Administración de Justicia mediante la institución del Jurado"},{"ref":"Art. 126 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"La policía judicial depende de los Jueces, de los Tribunales y del Ministerio Fiscal en sus funciones de averiguación del delito y descubrimiento y aseguramiento del delincuente"},{"ref":"Art. 127.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los Jueces y Magistrados así como los Fiscales, mientras se hallen en activo, no podrán desempeñar otros cargos públicos, ni pertenecer a partidos políticos o sindicatos."}]}]},{"n":"3","title":"La organización judicial: territorio y órganos","blocks":[{"text":"A efectos judiciales, el Estado se organiza en municipios, partidos, provincias y Comunidades Autónomas. Tras la reforma de la LO 1/2025, el artículo 26 LOPJ enumera los Tribunales que ejercen la potestad jurisdiccional: jueces y juezas de paz, Tribunales de Instancia, Audiencias Provinciales, Tribunales Superiores de Justicia, Tribunal Central de Instancia, Audiencia Nacional y Tribunal Supremo. Conviene memorizar la lista, porque los antiguos «Juzgados» unipersonales se integran ahora en los Tribunales de Instancia.","refs":[{"ref":"Art. 30 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Estado se organiza territorialmente, a efectos judiciales, en Municipios, Partidos, Provincias y Comunidades Autónomas."},{"ref":"Art. 26 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"a) Jueces y juezas de paz. […] b) Tribunales de Instancia. […] c) Audiencias Provinciales. […] d) Tribunales Superiores de Justicia. […] e) Tribunal Central de Instancia. […] f) Audiencia Nacional. […] g) Tribunal Supremo."}]},{"text":"Habrá un Tribunal de Instancia en cada partido judicial, con sede en su capital. Se compone de una Sección Única de Civil y de Instrucción (o de dos Secciones separadas) y puede tener otras secciones: Familia, Infancia y Capacidad; Mercantil; Violencia sobre la Mujer; Violencia contra la Infancia y la Adolescencia; Penal; Menores; Vigilancia Penitenciaria; Contencioso-Administrativo y Social.","refs":[{"ref":"Art. 84.1 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Habrá un Tribunal de Instancia en cada partido judicial, con sede en su capital, de la que tomará su nombre."},{"ref":"Art. 84.2 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"g) De Vigilancia Penitenciaria."}]},{"text":"En la cúspide está el Tribunal Supremo, con sede en Madrid y jurisdicción en toda España, órgano jurisdiccional superior en todos los órdenes salvo en materia de garantías constitucionales (que corresponde al Tribunal Constitucional). Su Presidente lo nombra el Rey a propuesta del CGPJ. La Audiencia Nacional también tiene sede en Madrid y jurisdicción en toda España.","refs":[{"ref":"Art. 123.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Tribunal Supremo, con jurisdicción en toda España, es el órgano jurisdiccional superior en todos los órdenes, salvo lo dispuesto en materia de garantías constitucionales."},{"ref":"Art. 123.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Presidente del Tribunal Supremo será nombrado por el Rey, a propuesta del Consejo General del Poder Judicial, en la forma que determine la ley."},{"ref":"Art. 62 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La Audiencia Nacional, con sede en la villa de Madrid, tiene jurisdicción en toda España."}]}]},{"n":"4","title":"Los órdenes jurisdiccionales y la Vigilancia Penitenciaria","blocks":[{"text":"La LOPJ distribuye los asuntos en cuatro órdenes ordinarios. El civil conoce de sus materias y de todas las que no estén atribuidas a otro orden; el penal, de las causas y juicios criminales (salvo la jurisdicción militar); el contencioso-administrativo, de la actuación de las Administraciones sujeta al Derecho administrativo; y el social, de la rama social del Derecho. La jurisdicción es improrrogable.","refs":[{"ref":"Art. 9.2 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los jueces y juezas, así como los Tribunales del orden civil conocerán, además de las materias que les son propias, de todas aquellas que no estén atribuidas a otro orden jurisdiccional."},{"ref":"Art. 9.3 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Los del orden jurisdiccional penal tendrán atribuido el conocimiento de las causas y juicios criminales, con excepción de los que correspondan a la jurisdicción militar."},{"ref":"Art. 9.6 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"La jurisdicción es improrrogable."}]},{"text":"Para el funcionario de prisiones es esencial la Sección de Vigilancia Penitenciaria, que existe con carácter general en el Tribunal de Instancia de cada capital de provincia, dentro del orden penal. Sus funciones: ejecución de penas privativas de libertad y medidas de seguridad, control jurisdiccional de la potestad disciplinaria de las autoridades penitenciarias y amparo de los derechos y beneficios de los internos. Su número y ámbito se fijan atendiendo principalmente a los establecimientos penitenciarios existentes.","refs":[{"ref":"Art. 92.1 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"en el Tribunal de Instancia con sede en la capital de cada provincia, dentro del orden jurisdiccional penal, existirá una Sección de Vigilancia Penitenciaria"},{"ref":"Art. 92.1 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"control jurisdiccional de la potestad disciplinaria de las autoridades penitenciarias, amparo de los derechos y beneficios de los internos en los establecimientos penitenciarios y demás que señale la ley."},{"ref":"Art. 92.3 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"atendiendo principalmente a los establecimientos penitenciarios existentes y a la clase de éstos."}]}]},{"n":"5","title":"Las actuaciones judiciales","blocks":[{"text":"La Constitución fija tres reglas: las actuaciones judiciales son públicas, con las excepciones de las leyes procesales; el procedimiento es predominantemente oral, sobre todo en materia criminal; y las sentencias se motivan siempre y se pronuncian en audiencia pública. La LOPJ permite excepcionalmente, por orden público o protección de derechos, limitar la publicidad y declarar secretas todas o parte de las actuaciones mediante resolución motivada.","refs":[{"ref":"Art. 120 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Las actuaciones judiciales serán públicas, con las excepciones que prevean las leyes de procedimiento."},{"ref":"Art. 120.2 y 120.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El procedimiento será predominantemente oral, sobre todo en materia criminal. […] Las sentencias serán siempre motivadas y se pronunciarán en audiencia pública."},{"ref":"Art. 232.3 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"podrán limitar el ámbito de la publicidad y acordar el carácter secreto de todas o parte de las actuaciones."}]},{"text":"Las declaraciones, testimonios o vistas pueden hacerse por videoconferencia si se garantiza la contradicción y el derecho de defensa. En cuanto a la lengua, jueces y funcionarios usan el castellano, lengua oficial del Estado, y pueden usar la lengua oficial propia de la Comunidad Autónoma si ninguna parte se opone alegando indefensión; las actuaciones en lengua autonómica tienen plena validez sin traducción.","refs":[{"ref":"Art. 229.3 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Estas actuaciones podrán realizarse a través de videoconferencia u otro sistema similar"},{"ref":"Art. 231.1 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"usarán el castellano, lengua oficial del Estado."},{"ref":"Art. 231.4 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Las actuaciones judiciales realizadas y los documentos presentados en el idioma oficial de una Comunidad Autónoma tendrán, sin necesidad de traducción al castellano, plena validez y eficacia."}]},{"text":"Son inhábiles los sábados, domingos y festivos, y son horas hábiles de ocho de la mañana a ocho de la tarde. Agosto y del 24 de diciembre al 6 de enero son inhábiles salvo actuaciones urgentes. Para la instrucción de causas criminales todos los días y horas son hábiles. Los plazos se computan según el Código Civil, excluyendo los inhábiles, y si el último día es inhábil se prorroga al siguiente hábil.","refs":[{"ref":"Art. 182.2 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Son horas hábiles desde las ocho de la mañana a las ocho de la tarde, salvo que la ley disponga lo contrario."},{"ref":"Art. 183 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Serán inhábiles los días del mes de agosto, así como todos los días desde el 24 de diciembre hasta el 6 de enero del año siguiente, ambos inclusive"},{"ref":"Art. 184.1 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"todos los días del año y todas las horas serán hábiles para la instrucción de las causas criminales, sin necesidad de habilitación especial."},{"ref":"Art. 185.2 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Si el último día de plazo fuere inhábil, se entenderá prorrogado al primer día hábil siguiente."}]}]},{"n":"6","title":"El Consejo General del Poder Judicial","blocks":[{"text":"El CGPJ es el órgano de gobierno del Poder Judicial, con sede en Madrid; sus funciones principales son los nombramientos, ascensos, inspección y régimen disciplinario de jueces y magistrados. Lo integran el Presidente del Tribunal Supremo, que lo preside, y veinte miembros nombrados por el Rey por cinco años: doce entre Jueces y Magistrados de todas las categorías y ocho entre abogados y otros juristas de reconocida competencia con más de quince años de ejercicio (cuatro a propuesta del Congreso y cuatro del Senado, por tres quintos).","refs":[{"ref":"Art. 122.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Consejo General del Poder Judicial es el órgano de gobierno del mismo."},{"ref":"Art. 122.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"en particular en materia de nombramientos, ascensos, inspección y régimen disciplinario."},{"ref":"Art. 122.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Consejo General del Poder Judicial estará integrado por el Presidente del Tribunal Supremo, que lo presidirá, y por veinte miembros nombrados por el Rey por un período de cinco años. De éstos, doce entre Jueces y Magistrados de todas las categorías judiciales"}]},{"text":"La LOPJ concreta que los veinte Vocales los designan las Cortes Generales: cada Cámara elige por tres quintos a diez (seis del turno judicial y cuatro juristas), atendiendo a la presencia equilibrada de mujeres y hombres. El Consejo se renueva en su totalidad cada cinco años y no pueden ser designados vocales del Consejo saliente.","refs":[{"ref":"Art. 567.2 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"Cada una de las Cámaras elegirá, por mayoría de tres quintos de sus miembros, a diez Vocales, cuatro entre juristas de reconocida competencia con más de quince años de ejercicio en su profesión y seis correspondientes al turno judicial"},{"ref":"Art. 568.1 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"El Consejo General del Poder Judicial se renovará en su totalidad cada cinco años, contados desde la fecha de su constitución."},{"ref":"Art. 567.5 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"En ningún caso podrá recaer la designación de Vocales del Consejo General del Poder Judicial en Vocales del Consejo saliente."}]}]},{"n":"7","title":"El Tribunal Constitucional: composición","blocks":[{"text":"El Tribunal Constitucional tiene 12 miembros nombrados por el Rey: cuatro a propuesta del Congreso por tres quintos, cuatro a propuesta del Senado con igual mayoría, dos a propuesta del Gobierno y dos a propuesta del CGPJ. Deben ser Magistrados y Fiscales, Profesores de Universidad, funcionarios públicos o Abogados, juristas de reconocida competencia con más de quince años de ejercicio profesional.","refs":[{"ref":"Art. 159.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Tribunal Constitucional se compone de 12 miembros nombrados por el Rey; de ellos, cuatro a propuesta del Congreso por mayoría de tres quintos de sus miembros; cuatro a propuesta del Senado, con idéntica mayoría; dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial."},{"ref":"Art. 159.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"todos ellos juristas de reconocida competencia con más de quince años de ejercicio profesional."}]},{"text":"Su mandato es de nueve años y se renuevan por terceras partes cada tres. Son independientes e inamovibles, y su cargo es incompatible con todo mandato representativo, cargos políticos o administrativos, funciones directivas en partidos o sindicatos, las carreras judicial y fiscal y cualquier actividad profesional o mercantil. El Presidente es nombrado por el Rey entre sus miembros, a propuesta del Pleno, por tres años.","refs":[{"ref":"Art. 159.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"serán designados por un período de nueve años y se renovarán por terceras partes cada tres."},{"ref":"Art. 159.5 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los miembros del Tribunal Constitucional serán independientes e inamovibles en el ejercicio de su mandato."},{"ref":"Art. 160 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Presidente del Tribunal Constitucional será nombrado entre sus miembros por el Rey, a propuesta del mismo Tribunal en pleno y por un período de tres años."}]}]},{"n":"8","title":"El Tribunal Constitucional: atribuciones, legitimación y sentencias","blocks":[{"text":"El TC tiene jurisdicción en todo el territorio y conoce del recurso de inconstitucionalidad contra leyes y normas con fuerza de ley, del recurso de amparo por violación de los derechos del artículo 53.2, de los conflictos de competencia entre el Estado y las Comunidades Autónomas o entre estas, y de lo demás que le atribuyan la Constitución o las leyes orgánicas. El Gobierno puede impugnar disposiciones autonómicas, lo que produce su suspensión, que el Tribunal debe ratificar o levantar en cinco meses como máximo.","refs":[{"ref":"Art. 161.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"a) Del recurso de inconstitucionalidad contra leyes y disposiciones normativas con fuerza de ley."},{"ref":"Art. 161.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"b) Del recurso de amparo por violación de los derechos y libertades referidos en el artículo 53, 2, de esta Constitución"},{"ref":"Art. 161.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"deberá ratificarla o levantarla en un plazo no superior a cinco meses."}]},{"text":"Están legitimados para el recurso de inconstitucionalidad el Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores y los órganos ejecutivos y, en su caso, las Asambleas de las Comunidades Autónomas. Para el amparo, toda persona natural o jurídica con interés legítimo, el Defensor del Pueblo y el Ministerio Fiscal. Además, cualquier juez que dude de la constitucionalidad de una ley aplicable de la que dependa el fallo plantea la cuestión de inconstitucionalidad, sin efectos suspensivos.","refs":[{"ref":"Art. 162.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Para interponer el recurso de inconstitucionalidad, el Presidente del Gobierno, el Defensor del Pueblo, 50 Diputados, 50 Senadores"},{"ref":"Art. 162.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Para interponer el recurso de amparo, toda persona natural o jurídica que invoque un interés legítimo, así como el Defensor del Pueblo y el Ministerio Fiscal."},{"ref":"Art. 163 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"que en ningún caso serán suspensivos."}]},{"text":"Las sentencias del TC se publican en el BOE con los votos particulares, tienen valor de cosa juzgada desde el día siguiente a su publicación y no cabe recurso contra ellas. Las que declaran la inconstitucionalidad de una ley tienen plenos efectos frente a todos.","refs":[{"ref":"Art. 164.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Tienen el valor de cosa juzgada a partir del día siguiente de su publicación y no cabe recurso alguno contra ellas."},{"ref":"Art. 164.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"tienen plenos efectos frente a todos."}]}]},{"n":"9","title":"El Ministerio Fiscal","blocks":[{"text":"El Ministerio Fiscal promueve la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados; vela por la independencia de los Tribunales y procura ante ellos la satisfacción del interés social. Es un órgano de relevancia constitucional, con personalidad jurídica propia, integrado con autonomía funcional en el Poder Judicial.","refs":[{"ref":"Art. 124.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"tiene por misión promover la acción de la justicia en defensa de la legalidad, de los derechos de los ciudadanos y del interés público tutelado por la ley, de oficio o a petición de los interesados"},{"ref":"Art. segundo.Uno EOMF","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"El Ministerio Fiscal es un órgano de relevancia constitucional con personalidad jurídica propia, integrado con autonomía funcional en el Poder Judicial"}]},{"text":"Actúa por medio de órganos propios conforme a dos principios orgánicos (unidad de actuación y dependencia jerárquica) y dos funcionales (legalidad e imparcialidad). Es único para todo el Estado y su jefatura superior corresponde al Fiscal General del Estado. Interesa especialmente que los fiscales pueden visitar en cualquier momento los centros penitenciarios de su territorio y examinar los expedientes de los internos.","refs":[{"ref":"Art. 124.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Ministerio Fiscal ejerce sus funciones por medio de órganos propios conforme a los principios de unidad de actuación y dependencia jerárquica y con sujeción, en todo caso, a los de legalidad e imparcialidad."},{"ref":"Art. veintidós.Uno EOMF","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"El Ministerio Fiscal es único para todo el Estado."},{"ref":"Art. cuarto.Dos EOMF","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"Visitar en cualquier momento los centros o establecimientos de detención, penitenciarios o de internamiento de cualquier clase de su respectivo territorio, examinar los expedientes de los internos"}]},{"text":"El Fiscal General del Estado lo nombra el Rey a propuesta del Gobierno, oído el CGPJ, entre juristas españoles de reconocido prestigio con más de quince años de ejercicio. Su mandato es de cuatro años, no renovable salvo que haya ejercido menos de dos, y cesa, entre otros motivos, cuando cesa el Gobierno que lo propuso.","refs":[{"ref":"Art. 124.4 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"El Fiscal General del Estado será nombrado por el Rey, a propuesta del Gobierno, oído el Consejo General del Poder Judicial."},{"ref":"Art. treinta y uno.Uno EOMF","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"El mandato del Fiscal General del Estado tendrá una duración de cuatro años."},{"ref":"Art. treinta y uno.Uno EOMF","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"e) cuando cese el Gobierno que lo hubiera propuesto."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Jueces y Magistrados: independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley.","refs":[{"ref":"Art. 117.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"independientes, inamovibles, responsables y sometidos únicamente al imperio de la ley."}]},{"text":"Juzgar y hacer ejecutar lo juzgado corresponde exclusivamente a Juzgados y Tribunales.","refs":[{"ref":"Art. 117.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"corresponde exclusivamente a los Juzgados y Tribunales determinados por las leyes"}]},{"text":"CGPJ: Presidente del TS más veinte vocales por cinco años; doce del turno judicial.","refs":[{"ref":"Art. 122.3 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"y por veinte miembros nombrados por el Rey por un período de cinco años."}]},{"text":"TC: 12 miembros (4 Congreso, 4 Senado, 2 Gobierno, 2 CGPJ), nueve años, renovación por tercios cada tres; Presidente por tres años.","refs":[{"ref":"Art. 159.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"dos a propuesta del Gobierno, y dos a propuesta del Consejo General del Poder Judicial."},{"ref":"Art. 160 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"por un período de tres años."}]},{"text":"Recurso de inconstitucionalidad: también el Defensor del Pueblo, 50 Diputados o 50 Senadores.","refs":[{"ref":"Art. 162.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"el Defensor del Pueblo, 50 Diputados, 50 Senadores"}]},{"text":"Sentencias del TC: cosa juzgada desde el día siguiente a su publicación, sin recurso.","refs":[{"ref":"Art. 164.1 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Tienen el valor de cosa juzgada a partir del día siguiente de su publicación"}]},{"text":"Fiscal General: nombrado por el Rey a propuesta del Gobierno, oído el CGPJ; mandato de cuatro años.","refs":[{"ref":"Art. 124.4 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"a propuesta del Gobierno, oído el Consejo General del Poder Judicial."},{"ref":"Art. treinta y uno.Uno EOMF","law":"Ley 50/1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1982-837","quote":"tendrá una duración de cuatro años."}]},{"text":"Principios del Ministerio Fiscal: unidad de actuación, dependencia jerárquica, legalidad e imparcialidad.","refs":[{"ref":"Art. 124.2 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"unidad de actuación y dependencia jerárquica"}]},{"text":"Agosto es inhábil, pero en la instrucción penal todos los días y horas son hábiles.","refs":[{"ref":"Art. 184.1 LOPJ","law":"LOPJ","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1985-12666","quote":"todos los días del año y todas las horas serán hábiles para la instrucción de las causas criminales"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229', null, null, null, null
