insert into public.sources (title, url, kind, publisher, published_on) values ('Ley Orgánica 3/2007, de 22 de marzo, para la igualdad efectiva de mujeres y hombres (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('iipp-a12-politicas-publicas-igualdad-dependencia', 'Primera parte, tema 12. Políticas de igualdad, violencia de género, discapacidad, dependencia y administración electrónica') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-a12-politicas-publicas-igualdad-dependencia' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Igualdad efectiva de mujeres y hombres (LO 3/2007)"},{"n":"2","title":"Violencia de género (LO 1/2004)"},{"n":"3","title":"Autonomía personal y dependencia (Ley 39/2006)"},{"n":"4","title":"Administración electrónica: derecho y obligación de relacionarse electrónicamente (art. 14 LPAC)"},{"n":"5","title":"Registros y notificaciones electrónicas (arts. 16, 41 y 43 LPAC)"}]'::jsonb, '["Art. 3 LO 3/2007: «El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo»","Art. 4 LO 3/2007: «es un principio informador del ordenamiento jurídico y, como tal, se integrará y observará en la interpretación y aplicación de las normas jurídicas.»","Art. 6.1 LO 3/2007: «Se considera discriminación directa por razón de sexo la situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable.»","Art. 7.1 LO 3/2007: «constituye acoso sexual cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona»","Art. 11.1 LO 3/2007: «Tales medidas, que serán aplicables en tanto subsistan dichas situaciones, habrán de ser razonables y proporcionadas»","Art. 17 LO 3/2007: «El Gobierno, en las materias que sean de la competencia del Estado, aprobará periódicamente un Plan Estratégico de Igualdad de Oportunidades»","Art. 1.1 LO 1/2004: «por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia.»","Art. 1.1 LO 1/2004: «como manifestación de la discriminación, la situación de desigualdad y las relaciones de poder de los hombres sobre las mujeres»","Art. 2 LO 1/2004: «a) Fortalecer las medidas de sensibilización ciudadana de prevención»","Art. 1.1 Ley 39/2006: «mediante la creación de un Sistema para la Autonomía y Atención a la Dependencia»","Art. 2 Ley 39/2006: «Autonomía: la capacidad de controlar, afrontar y tomar, por propia iniciativa, decisiones personales acerca de cómo vivir»","Art. 26.1 Ley 39/2006: «b) Grado II. Dependencia severa: cuando la persona necesita ayuda para realizar varias actividades de la vida diaria dos o tres veces al día»","Art. 28.1 Ley 39/2006: «estableciéndose un plazo máximo de 3 meses para su resolución.»","Art. 14.1 Ley 39/2015: «Las personas físicas podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Políticas públicas de igualdad: objeto y principio de igualdad de trato (LO 3/2007)","blocks":[{"text":"La Ley Orgánica 3/2007, para la igualdad efectiva de mujeres y hombres, desarrolla los artículos 9.2 y 14 de la Constitución y tiene por objeto hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres, en particular eliminando la discriminación de la mujer en cualquier ámbito de la vida (art. 1.1). Sus obligaciones alcanzan a toda persona física o jurídica que se encuentre o actúe en territorio español, cualquiera que sea su nacionalidad, domicilio o residencia (art. 2.2).","refs":[{"ref":"Art. 1.1 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"Esta Ley tiene por objeto hacer efectivo el derecho de igualdad de trato y de oportunidades entre mujeres y hombres, en particular mediante la eliminación de la discriminación de la mujer"},{"ref":"Art. 2.2 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"Las obligaciones establecidas en esta Ley serán de aplicación a toda persona, física o jurídica, que se encuentre o actúe en territorio español, cualquiera que fuese su nacionalidad, domicilio o residencia."}]},{"text":"El principio de igualdad de trato supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y especialmente las derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil (art. 3). La igualdad es además un principio informador del ordenamiento jurídico, que se integra y observa en la interpretación y aplicación de las normas (art. 4). Rige tanto en el empleo privado como en el público: acceso, formación, promoción y condiciones de trabajo (art. 5).","refs":[{"ref":"Art. 3 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"El principio de igualdad de trato entre mujeres y hombres supone la ausencia de toda discriminación, directa o indirecta, por razón de sexo, y, especialmente, las derivadas de la maternidad, la asunción de obligaciones familiares y el estado civil."},{"ref":"Art. 4 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"La igualdad de trato y de oportunidades entre mujeres y hombres es un principio informador del ordenamiento jurídico y, como tal, se integrará y observará en la interpretación y aplicación de las normas jurídicas."}]}]},{"n":"2","title":"Discriminación, acoso y acciones positivas","blocks":[{"text":"Hay discriminación directa cuando una persona es, ha sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable (art. 6.1). Hay discriminación indirecta cuando una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular, salvo justificación objetiva por una finalidad legítima con medios necesarios y adecuados (art. 6.2). Todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad es discriminación directa (art. 8), y también lo es cualquier represalia por presentar una queja o denuncia contra la discriminación (art. 9).","refs":[{"ref":"Art. 6.1 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"Se considera discriminación directa por razón de sexo la situación en que se encuentra una persona que sea, haya sido o pudiera ser tratada, en atención a su sexo, de manera menos favorable que otra en situación comparable."},{"ref":"Art. 6.2 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"Se considera discriminación indirecta por razón de sexo la situación en que una disposición, criterio o práctica aparentemente neutros pone a personas de un sexo en desventaja particular con respecto a personas del otro"},{"ref":"Art. 8 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"Constituye discriminación directa por razón de sexo todo trato desfavorable a las mujeres relacionado con el embarazo o la maternidad."}]},{"text":"La ley distingue el acoso sexual, que es cualquier comportamiento verbal o físico de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona, del acoso por razón de sexo, que es el comportamiento realizado en función del sexo de una persona con ese propósito o efecto y de crear un entorno intimidatorio, degradante u ofensivo (art. 7). Ambos son siempre discriminatorios (art. 7.3). Los actos y cláusulas discriminatorios son nulos y sin efecto (art. 10).","refs":[{"ref":"Art. 7.1 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"constituye acoso sexual cualquier comportamiento, verbal o físico, de naturaleza sexual que tenga el propósito o produzca el efecto de atentar contra la dignidad de una persona, en particular cuando se crea un entorno intimidatorio, degradante u ofensivo."},{"ref":"Art. 7.2 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"Constituye acoso por razón de sexo cualquier comportamiento realizado en función del sexo de una persona, con el propósito o el efecto de atentar contra su dignidad y de crear un entorno intimidatorio, degradante u ofensivo."},{"ref":"Art. 10 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"Los actos y las cláusulas de los negocios jurídicos que constituyan o causen discriminación por razón de sexo se considerarán nulos y sin efecto"}]},{"text":"Las acciones positivas son medidas específicas a favor de las mujeres para corregir situaciones patentes de desigualdad de hecho; solo se aplican mientras subsistan esas situaciones y deben ser razonables y proporcionadas al objetivo (art. 11.1). También pueden adoptarlas las personas privadas (art. 11.2).","refs":[{"ref":"Art. 11.1 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"los Poderes Públicos adoptarán medidas específicas en favor de las mujeres para corregir situaciones patentes de desigualdad de hecho respecto de los hombres. Tales medidas, que serán aplicables en tanto subsistan dichas situaciones, habrán de ser razonables y proporcionadas en relación con el objetivo perseguido en cada caso."}]}]},{"n":"3","title":"Instrumentos de igualdad y empleo público","blocks":[{"text":"En las materias de competencia estatal, el Gobierno aprueba periódicamente un Plan Estratégico de Igualdad de Oportunidades, con medidas para alcanzar la igualdad y eliminar la discriminación por razón de sexo (art. 17). Para su propio personal, las Administraciones públicas deben, entre otras cosas, remover obstáculos en el acceso y la carrera, facilitar la conciliación, promover la presencia equilibrada en órganos de selección y valoración y establecer medidas frente al acoso (art. 51). El Gobierno aprueba al inicio de cada legislatura un Plan para la Igualdad en la Administración General del Estado (art. 64), y las Administraciones negocian con la representación del personal un protocolo frente al acoso sexual y por razón de sexo (art. 62).","refs":[{"ref":"Art. 17 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"El Gobierno, en las materias que sean de la competencia del Estado, aprobará periódicamente un Plan Estratégico de Igualdad de Oportunidades"},{"ref":"Art. 51 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"d) Promover la presencia equilibrada de mujeres y hombres en los órganos de selección y valoración. e) Establecer medidas efectivas de protección frente al acoso sexual y al acoso por razón de sexo."},{"ref":"Art. 64 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"El Gobierno aprobará, al inicio de cada legislatura, un Plan para la Igualdad entre mujeres y hombres en la Administración General del Estado"},{"ref":"Art. 62 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"las Administraciones públicas negociarán con la representación legal de las trabajadoras y trabajadores, un protocolo de actuación"}]}]},{"n":"4","title":"Políticas contra la violencia de género: objeto y principios (LO 1/2004)","blocks":[{"text":"La Ley Orgánica 1/2004, de Medidas de Protección Integral contra la Violencia de Género, actúa contra la violencia que, como manifestación de la discriminación, la situación de desigualdad y las relaciones de poder de los hombres sobre las mujeres, se ejerce sobre ellas por quienes sean o hayan sido sus cónyuges o estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia (art. 1.1). Comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones y la privación arbitraria de libertad (art. 1.3), y también la violencia ejercida sobre familiares o allegados menores para dañar a la mujer (art. 1.4).","refs":[{"ref":"Art. 1.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"La presente Ley tiene por objeto actuar contra la violencia que, como manifestación de la discriminación, la situación de desigualdad y las relaciones de poder de los hombres sobre las mujeres, se ejerce sobre éstas por parte de quienes sean o hayan sido sus cónyuges o de quienes estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia."},{"ref":"Art. 1.3 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"comprende todo acto de violencia física y psicológica, incluidas las agresiones a la libertad sexual, las amenazas, las coacciones o la privación arbitraria de libertad."}]},{"text":"La ley establece medidas de protección integral para prevenir, sancionar y erradicar esta violencia y asistir a las mujeres y a sus hijos menores (art. 1.2). Sus fines (art. 2) incluyen fortalecer las medidas de sensibilización ciudadana de prevención, consagrar derechos de las víctimas exigibles ante las Administraciones, garantizar derechos laborales, funcionariales y económicos, establecer un sistema integral de tutela institucional y fortalecer el marco penal y procesal.","refs":[{"ref":"Art. 2 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"a) Fortalecer las medidas de sensibilización ciudadana de prevención, dotando a los poderes públicos de instrumentos eficaces en el ámbito educativo, servicios sociales, sanitario, publicitario y mediático."},{"ref":"Art. 2 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"d) Garantizar derechos en el ámbito laboral y funcionarial que concilien los requerimientos de la relación laboral y de empleo público con las circunstancias de aquellas trabajadoras o funcionarias que sufran violencia de género."}]}]},{"n":"5","title":"Derechos de las víctimas, tutela institucional y Administración penitenciaria","blocks":[{"text":"Todas las víctimas tienen garantizados los derechos de la ley sin discriminación (art. 17.1): información, asistencia social integral y asistencia jurídica. La funcionaria víctima tiene derecho a la reducción o reordenación de su tiempo de trabajo, a la movilidad geográfica y a la excedencia en los términos de su legislación específica (art. 24), y sus ausencias motivadas por la violencia sufrida se consideran justificadas (art. 25). La Delegación del Gobierno contra la Violencia de Género formula las políticas públicas en la materia y elabora la Macroencuesta (art. 29.1).","refs":[{"ref":"Art. 17.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Todas las mujeres víctimas de violencia de género tienen garantizados los derechos reconocidos en esta ley, sin que pueda existir discriminación en el acceso a los mismos."},{"ref":"Art. 24 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"La funcionaria víctima de violencia de género tendrá derecho a la reducción o a la reordenación de su tiempo de trabajo, a la movilidad geográfica de centro de trabajo y a la excedencia en los términos que se determinen en su legislación específica."},{"ref":"Art. 29.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"formulará las políticas públicas en relación con la violencia de género a desarrollar por el Gobierno y elaborará la Macroencuesta de Violencia contra las Mujeres."}]},{"text":"Para el opositor a prisiones es clave el artículo 42: la Administración penitenciaria realizará programas específicos para internos condenados por delitos relacionados con la violencia de género, y las Juntas de Tratamiento valorarán su seguimiento y aprovechamiento en las progresiones de grado, la concesión de permisos y la libertad condicional.","refs":[{"ref":"Art. 42 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"1. La Administración penitenciaria realizará programas específicos para internos condenados por delitos relacionados con la violencia de género. 2. Las Juntas de Tratamiento valorarán, en las progresiones de grado, concesión de permisos y concesión de la libertad condicional, el seguimiento y aprovechamiento de dichos programas específicos"},{"ref":"Art. 116.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"La Administración Penitenciaria podrá realizar programas específicos de tratamiento para internos condenados por delitos contra la libertad sexual"}]}]},{"n":"6","title":"Políticas de integración de las personas con discapacidad","blocks":[{"text":"La base constitucional está en el artículo 49 de la Constitución, reformado en 2024: las personas con discapacidad ejercen los derechos del Título I en condiciones de libertad e igualdad reales y efectivas, y los poderes públicos impulsan políticas que garanticen su plena autonomía personal e inclusión social en entornos universalmente accesibles, atendiendo especialmente a las mujeres y menores con discapacidad. La Ley 39/2006 conecta con esta política al definir la autonomía y la vida independiente. Este punto del programa no está desarrollado en las fuentes oficiales disponibles más allá de estas normas: falta el texto refundido de la Ley General de derechos de las personas con discapacidad (Real Decreto Legislativo 1/2013), que no se cita aquí.","refs":[{"ref":"Art. 49 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Las personas con discapacidad ejercen los derechos previstos en este Título en condiciones de libertad e igualdad reales y efectivas."},{"ref":"Art. 49 CE","law":"CE","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1978-31229","quote":"Los poderes públicos impulsarán las políticas que garanticen la plena autonomía personal y la inclusión social de las personas con discapacidad, en entornos universalmente accesibles."},{"ref":"Art. 2 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"Vida independiente: derecho fundamentado en la autodeterminación, la igualdad de oportunidades y el control sobre la propia vida, que garantiza que las personas con discapacidad decidan cómo, dónde y con quién vivir"}]}]},{"n":"7","title":"Régimen jurídico de la dependencia: objeto, conceptos y titulares (Ley 39/2006)","blocks":[{"text":"La Ley 39/2006 regula las condiciones básicas que garantizan la igualdad en el ejercicio del derecho subjetivo de ciudadanía a la promoción de la autonomía personal y atención a las personas en situación de dependencia, mediante la creación de un Sistema para la Autonomía y Atención a la Dependencia (SAAD) (art. 1.1). El Sistema es una red de utilización pública que integra de forma coordinada centros y servicios públicos y privados (art. 6.2), con tres niveles de protección: el mínimo fijado por la Administración General del Estado, el acordado con cada comunidad autónoma y el adicional autonómico (art. 7).","refs":[{"ref":"Art. 1.1 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"regular las condiciones básicas que garanticen la igualdad en el ejercicio del derecho subjetivo de ciudadanía a la promoción de la autonomía personal y atención a las personas en situación de dependencia, en los términos establecidos en las leyes, mediante la creación de un Sistema para la Autonomía y Atención a la Dependencia"},{"ref":"Art. 6.2 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"El Sistema se configura como una red de utilización pública que integra, de forma coordinada, centros y servicios, públicos y privados."},{"ref":"Art. 7 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"1.º El nivel de protección mínimo establecido por la Administración General del Estado en aplicación del artícu­lo 9."}]},{"text":"Autonomía es la capacidad de controlar, afrontar y tomar, por propia iniciativa, decisiones personales acerca de cómo vivir y de desarrollar las actividades de la vida diaria (art. 2.1). Dependencia es el estado de carácter permanente en que las personas precisan cuidados y apoyos de otras o ayudas importantes para las actividades de la vida diaria (art. 2.2). Son titulares los españoles en situación de dependencia que residan en España y lo hayan hecho cinco años, dos de ellos inmediatamente anteriores a la solicitud (art. 5.1). La Ley 4/2026 ha modificado recientemente varios preceptos, entre ellos el antiguo término «actividades básicas de la vida diaria», hoy «actividades de la vida diaria».","refs":[{"ref":"Art. 2.1 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"Autonomía: la capacidad de controlar, afrontar y tomar, por propia iniciativa, decisiones personales acerca de cómo vivir de acuerdo con las normas y preferencias propias así como de desarrollar las actividades de la vida diaria."},{"ref":"Art. 2.2 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"Situación de dependencia: el estado de carácter permanente en el que las personas, debido a dificultades que afectan a su autonomía, precisan de cuidados y apoyos de otra u otras personas o ayudas importantes para realizar actividades de la vida diaria."},{"ref":"Art. 5.1 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"Residir en territorio español y haberlo hecho durante cinco años, de los cuales dos deberán ser inmediatamente anteriores a la fecha de presentación de la solicitud."}]}]},{"n":"8","title":"Grados de dependencia, prestaciones y procedimiento","blocks":[{"text":"Hay tres grados (art. 26.1): Grado I, dependencia moderada, cuando se necesita ayuda para varias actividades de la vida diaria al menos una vez al día; Grado II, dependencia severa, cuando se necesita ayuda dos o tres veces al día pero no el apoyo permanente de una persona cuidadora; y Grado III, gran dependencia, cuando se necesita ayuda varias veces al día y, por pérdida total de autonomía, el apoyo indispensable y continuo de otra persona. El grado se determina con el baremo acordado en el Consejo Territorial y aprobado por real decreto (art. 27.2).","refs":[{"ref":"Art. 26.1 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"a) Grado I. Dependencia moderada: cuando la persona necesita ayuda para realizar varias actividades de la vida diaria, al menos una vez al día"},{"ref":"Art. 26.1 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"b) Grado II. Dependencia severa: cuando la persona necesita ayuda para realizar varias actividades de la vida diaria dos o tres veces al día, pero no requiere el apoyo permanente de una persona cuidadora"},{"ref":"Art. 26.1 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"c) Grado III. Gran dependencia: cuando la persona necesita ayuda para realizar varias actividades de la vida diaria varias veces al día"}]},{"text":"Las prestaciones pueden ser servicios o prestaciones económicas (art. 14.1); los servicios del Catálogo tienen carácter prioritario (art. 14.3). El Catálogo (art. 15.1) incluye prevención, promoción de la autonomía personal, teleasistencia, ayuda a domicilio, asistencia personal, centro de día y de noche, cuidados y apoyos en viviendas, atención residencial y provisión de productos de apoyo. Las prestaciones económicas son inembargables, salvo el supuesto del artículo 608 de la Ley de Enjuiciamiento Civil (art. 14.9).","refs":[{"ref":"Art. 14.3 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"Los servicios del Catálogo previstos en el artículo 15 tendrán carácter prioritario"},{"ref":"Art. 15.1 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"c) Servicio de teleasistencia. d) Servicio de ayuda a domicilio. e) Servicio de asistencia personal. f) Servicio de centro de día y de noche."},{"ref":"Art. 14.9 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"Las prestaciones económicas establecidas en virtud de esta ley serán inembargables"}]},{"text":"El procedimiento se inicia a instancia de la persona afectada o de su representante y tiene un plazo máximo de resolución de 3 meses (art. 28.1). Lo resuelve la Administración autonómica de la residencia del solicitante y la resolución vale en todo el Estado (art. 28.2). La valoración y la gestión de las prestaciones económicas no pueden delegarse ni contratarse con entidades privadas (art. 28.6). Se tramita de urgencia, entre otros casos, cuando el régimen penal penitenciario sitúa a la persona en especial vulnerabilidad (art. 28.7). Después, los servicios sociales y la persona establecen el Programa Individual de Atención (art. 29.1).","refs":[{"ref":"Art. 28.1 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"El procedimiento se iniciará a instancia de la persona que pueda estar afectada por algún grado de dependencia o de quien ostente su representación, estableciéndose un plazo máximo de 3 meses para su resolución."},{"ref":"Art. 28.2 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"El reconocimiento de la situación de dependencia se efectuará mediante resolución expedida por la Administración Autonómica correspondiente a la residencia del solicitante y tendrá validez en todo el territorio del Estado."},{"ref":"Art. 28.7 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"régimen penal penitenciario o violencia de género o sexual sitúen a la persona en una situación de especial vulnerabilidad. En estos casos, el expediente se tramitará de urgencia."}]}]},{"n":"9","title":"Administración electrónica: derecho y obligación de relacionarse electrónicamente","blocks":[{"text":"Las personas físicas pueden elegir en todo momento si se comunican con las Administraciones por medios electrónicos o no, salvo que estén obligadas, y pueden cambiar el medio elegido (art. 14.1 Ley 39/2015). Están obligados en todo caso (art. 14.2): las personas jurídicas; las entidades sin personalidad jurídica; quienes ejerzan una actividad con colegiación obligatoria, en esa actividad; quienes representen a un obligado; y los empleados públicos para los trámites que realicen por razón de su condición de empleado público. Reglamentariamente se puede extender la obligación a colectivos de personas físicas con acceso acreditado a medios electrónicos (art. 14.3).","refs":[{"ref":"Art. 14.1 Ley 39/2015","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las personas físicas podrán elegir en todo momento si se comunican con las Administraciones Públicas para el ejercicio de sus derechos y obligaciones a través de medios electrónicos o no, salvo que estén obligadas a relacionarse a través de medios electrónicos con las Administraciones Públicas."},{"ref":"Art. 14.2 Ley 39/2015","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) Las personas jurídicas. b) Las entidades sin personalidad jurídica."},{"ref":"Art. 14.2 Ley 39/2015","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"e) Los empleados de las Administraciones Públicas para los trámites y actuaciones que realicen con ellas por razón de su condición de empleado público"}]},{"text":"Las Administraciones deben asistir en el uso de medios electrónicos a quienes no estén obligados y lo soliciten, y si el interesado carece de medios, su identificación o firma puede hacerla un funcionario habilitado con su consentimiento expreso (art. 12.2). Entre los derechos de las personas figuran comunicarse a través de un Punto de Acceso General electrónico y ser asistidos en el uso de medios electrónicos (art. 13).","refs":[{"ref":"Art. 12.2 Ley 39/2015","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"su identificación o firma electrónica en el procedimiento administrativo podrá ser válidamente realizada por un funcionario público mediante el uso del sistema de firma electrónica del que esté dotado para ello."},{"ref":"Art. 13 Ley 39/2015","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"a) A comunicarse con las Administraciones Públicas a través de un Punto de Acceso General electrónico de la Administración. b) A ser asistidos en el uso de medios electrónicos en sus relaciones con las Administraciones Públicas."}]}]},{"n":"10","title":"Registro electrónico y notificaciones electrónicas","blocks":[{"text":"Cada Administración dispone de un Registro Electrónico General en el que se asienta todo documento presentado o recibido (art. 16.1). Los documentos pueden presentarse en el registro electrónico de cualquier Administración, en Correos, en representaciones diplomáticas y oficinas consulares, en las oficinas de asistencia en materia de registros y en cualquier otro lugar que establezcan las normas (art. 16.4). Lo presentado en papel se digitaliza y se devuelve el original al interesado (art. 16.5).","refs":[{"ref":"Art. 16.1 Ley 39/2015","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Cada Administración dispondrá de un Registro Electrónico General, en el que se hará el correspondiente asiento de todo documento que sea presentado o que se reciba en cualquier órgano administrativo"},{"ref":"Art. 16.4 Ley 39/2015","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"b) En las oficinas de Correos, en la forma que reglamentariamente se establezca. c) En las representaciones diplomáticas u oficinas consulares de España en el extranjero. d) En las oficinas de asistencia en materia de registros."}]},{"text":"Las notificaciones se practican preferentemente por medios electrónicos y, en todo caso, cuando el interesado esté obligado (art. 41.1). Nunca son electrónicas las que llevan elementos no convertibles a formato electrónico ni las que contienen medios de pago como cheques (art. 41.2). La notificación electrónica se practica por comparecencia en la sede electrónica o en la dirección electrónica habilitada única y se entiende practicada al acceder a su contenido; si es obligatoria o fue elegida, se entiende rechazada cuando pasan diez días naturales desde la puesta a disposición sin acceder (art. 43.1 y 43.2).","refs":[{"ref":"Art. 41.1 Ley 39/2015","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"Las notificaciones se practicarán preferentemente por medios electrónicos y, en todo caso, cuando el interesado resulte obligado a recibirlas por esta vía."},{"ref":"Art. 41.2 Ley 39/2015","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"b) Las que contengan medios de pago a favor de los obligados, tales como cheques."},{"ref":"Art. 43.2 Ley 39/2015","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"se entenderá rechazada cuando hayan transcurrido diez días naturales desde la puesta a disposición de la notificación sin que se acceda a su contenido."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Igualdad de trato = ausencia de toda discriminación, directa o indirecta, por razón de sexo; es principio informador del ordenamiento.","refs":[{"ref":"Art. 4 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"es un principio informador del ordenamiento jurídico"}]},{"text":"Acciones positivas: temporales (mientras subsista la desigualdad), razonables y proporcionadas.","refs":[{"ref":"Art. 11.1 LO 3/2007","law":"LO 3/2007","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115","quote":"serán aplicables en tanto subsistan dichas situaciones"}]},{"text":"Violencia de género (LO 1/2004): la ejercida por cónyuge o pareja, actual o pasada, aun sin convivencia.","refs":[{"ref":"Art. 1.1 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"aun sin convivencia"}]},{"text":"Prisiones: programas específicos para condenados por violencia de género, valorados por la Junta de Tratamiento en grados, permisos y libertad condicional.","refs":[{"ref":"Art. 42.2 LO 1/2004","law":"LO 1/2004","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760","quote":"Las Juntas de Tratamiento valorarán, en las progresiones de grado, concesión de permisos y concesión de la libertad condicional"}]},{"text":"Dependencia: Grado I moderada, II severa, III gran dependencia; resolución en un plazo máximo de 3 meses por la comunidad autónoma.","refs":[{"ref":"Art. 26.1 Ley 39/2006","law":"Ley 39/2006","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990","quote":"c) Grado III. Gran dependencia"}]},{"text":"Obligados a relacionarse electrónicamente: personas jurídicas, entes sin personalidad, colegiados, representantes de obligados y empleados públicos por razón de su condición.","refs":[{"ref":"Art. 14.2 Ley 39/2015","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"d) Quienes representen a un interesado que esté obligado a relacionarse electrónicamente con la Administración."}]},{"text":"Notificación electrónica no abierta en diez días naturales: se entiende rechazada.","refs":[{"ref":"Art. 43.2 Ley 39/2015","law":"Ley 39/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565","quote":"diez días naturales"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115'), 'https://www.boe.es/buscar/act.php?id=BOE-A-2007-6115', null, null, null, 'Otras normas citadas: LO 1/2004 (https://www.boe.es/buscar/act.php?id=BOE-A-2004-21760), Ley 39/2006 (https://www.boe.es/buscar/act.php?id=BOE-A-2006-21990), Ley 39/2015 (https://www.boe.es/buscar/act.php?id=BOE-A-2015-10565)'
  from public.topics t where t.slug = 'iipp-a12-politicas-publicas-igualdad-dependencia'
