   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 190/1996, de 9 de febrero, por el que se aprueba el Reglamento Penitenciario (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('iipp-c06-seguridad-medios-coercitivos', 'Derecho Penitenciario, tema 6. Régimen (2): seguridad exterior e interior y medios coercitivos') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c06-seguridad-medios-coercitivos' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Seguridad exterior (art. 63 RP)"},{"n":"2","title":"Seguridad interior: observación, recuentos, registros y cacheos (arts. 64-68 RP)"},{"n":"3","title":"Medios coercitivos (art. 45 LOGP; art. 72 RP)"},{"n":"4","title":"Protección y limitaciones regimentales (arts. 71 y 75 RP)"}]'::jsonb, '["Art. 63.1 RP: «La seguridad exterior de los Establecimientos corresponde a las Fuerzas y Cuerpos de Seguridad del Estado o, en su caso, a los Cuerpos de Policía de las Comunidades Autónomas»","Art. 63.2 RP: «Una vez practicado el relevo, el Jefe de la guardia exterior deberá presentarse al Director o funcionario que le sustituya para informarle de las incidencias del servicio.»","Art. 64 RP: «La seguridad interior de los Establecimientos corresponde, salvo en los casos previstos en la disposición final primera de la Ley Orgánica General Penitenciaria, a los funcionarios de los Cuerpos de Instituciones Penitenciarias»","Art. 65.1 RP: «Las actuaciones encaminadas a garantizar la seguridad interior de los establecimientos consistirán en la observación de los internos, los recuentos de población reclusa, los registros, los cacheos, las requisas, los controles, los cambios de celda, la asignación adecuada de destinos»","Art. 65.3 RP: «Al fin señalado en el apartado anterior, la Administración penitenciaria podrá constituir grupos especializados de funcionarios.»","Art. 66 RP: «Si en dicha observación se detectaran hechos o circunstancias que pudieran ser relevantes para la seguridad del Establecimiento o el tratamiento de los internos, se elevarán los oportunos informes.»","Art. 67.1 RP: «Se realizarán diariamente los recuentos ordinarios de control de la población reclusa en los momentos de la jornada regimental que coincidan con los relevos del personal de vigilancia»","Art. 67.2 RP: «También se efectuarán los recuentos extraordinarios que se ordenen por el Jefe de Servicios, comunicándolo a la Dirección»","Art. 67.3 RP: «sus resultados se reflejarán en parte escrito suscrito por los funcionarios que los hubiesen efectuado, que se dirigirá al Jefe de Servicios.»","Art. 68.2 RP: «se podrá realizar cacheo con desnudo integral con autorización del Jefe de Servicios.»","Art. 68.2 RP: «Por motivos de seguridad concretos y específicos, cuando existan razones individuales y contrastadas que hagan pensar que el interno oculta en su cuerpo algún objeto peligroso o sustancia susceptible de causar daño»","Art. 68.3 RP: «El cacheo con desnudo integral se efectuará por funcionarios del mismo sexo que el interno, en lugar cerrado sin la presencia de otros internos y preservando, en todo lo posible, la intimidad.»","Art. 68.4 RP: «Si el resultado del cacheo con desnudo integral fuese infructuoso y persistiese la sospecha, se podrá solicitar por el Director a la Autoridad judicial competente la autorización para la aplicación de otros medios de control adecuados.»","Art. 71.1 RP: «Ante la opción de utilizar medios de igual eficacia, se dará preferencia a los de carácter electrónico.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"La seguridad en los establecimientos: ubicación y reparto de competencias","blocks":[{"text":"El Reglamento Penitenciario regula la seguridad en el capítulo VIII del Título II, dividido en tres secciones: seguridad exterior, seguridad interior y medios coercitivos. La idea básica es un reparto de papeles: fuera de los muros actúan las Fuerzas y Cuerpos de Seguridad; dentro, los funcionarios de Instituciones Penitenciarias. Recuerda que estas funciones regimentales son medios para lograr una convivencia ordenada y deben ser proporcionadas a su fin (art. 73.2 RP).","refs":[{"ref":"Capítulo VIII RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"CAPITULO VIII. De la seguridad de los Establecimientos"},{"ref":"Art. 73.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Las funciones regimentales de seguridad, orden y disciplina son medios para alcanzar los fines indicados, debiendo ser siempre proporcionadas al fin que persiguen"}]},{"text":"Hay una excepción prevista en la propia LOGP: ante graves alteraciones del orden que obliguen a requerir la intervención de los Cuerpos de Seguridad del Estado, el jefe de esas fuerzas asume la dirección del establecimiento en cuanto a custodia, vigilancia y restauración del orden, mientras la autoridad penitenciaria sigue dirigiendo el tratamiento, las relaciones con los jueces, el régimen económico-administrativo y las funciones asistenciales (disposición final primera LOGP).","refs":[{"ref":"Disposición final primera LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"Desde el momento en que intervengan dichas fuerzas asumirá la dirección del establecimiento penitenciario en cuanto a custodia, vigilancia y restauración del orden el jefe de las mismas, sin perjuicio de continuar la autoridad penitenciaria en la dirección de las actividades de tratamiento"}]}]},{"n":"2","title":"La seguridad exterior: competencia y fines","blocks":[{"text":"La seguridad exterior corresponde a las Fuerzas y Cuerpos de Seguridad del Estado o, en su caso, a las policías autonómicas. Se rigen por sus propias normas, pero en esta materia reciben indicaciones de los Directores de los centros (art. 63.1 RP). Su finalidad es proteger el perímetro del establecimiento, de modo que la custodia interior queda en manos del personal penitenciario.","refs":[{"ref":"Art. 63.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"La seguridad exterior de los Establecimientos corresponde a las Fuerzas y Cuerpos de Seguridad del Estado o, en su caso, a los Cuerpos de Policía de las Comunidades Autónomas, los que, sin perjuicio de que se rijan por las normas de los Cuerpos respectivos, en materia de seguridad exterior de los Centros penitenciarios recibirán indicaciones de los Directores de los mismos."}]},{"text":"Tras cada relevo, el Jefe de la guardia exterior debe presentarse al Director, o al funcionario que lo sustituya, para informarle de las incidencias del servicio. Lo mismo hará cuando durante el servicio ocurra algo tan importante que deba conocerlo el Director de inmediato (art. 63.2 RP).","refs":[{"ref":"Art. 63.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Una vez practicado el relevo, el Jefe de la guardia exterior deberá presentarse al Director o funcionario que le sustituya para informarle de las incidencias del servicio. De igual forma procederá cuando durante el servicio se produzca algún hecho que, por su importancia, deba ser puesto inmediatamente en conocimiento del Director del Establecimiento."}]},{"text":"El programa habla de los «fines» de la seguridad exterior; el RP no los enumera expresamente más allá de atribuir la competencia y ordenar la coordinación con el Director, por lo que este punto no está más desarrollado en las fuentes oficiales disponibles.","refs":[{"ref":"Art. 63.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"en materia de seguridad exterior de los Centros penitenciarios recibirán indicaciones de los Directores de los mismos."}]}]},{"n":"3","title":"La seguridad interior: competencia y medidas","blocks":[{"text":"La seguridad interior corresponde a los funcionarios de los Cuerpos de Instituciones Penitenciarias, según los cometidos de cada uno y la distribución de servicios que acuerde el Director, salvo los casos de la disposición final primera de la LOGP (art. 64 RP).","refs":[{"ref":"Art. 64 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"La seguridad interior de los Establecimientos corresponde, salvo en los casos previstos en la disposición final primera de la Ley Orgánica General Penitenciaria, a los funcionarios de los Cuerpos de Instituciones Penitenciarias, con arreglo a los cometidos propios de cada uno y a la distribución de los servicios acordada por el Director del Establecimiento."}]},{"text":"El artículo 65.1 RP enumera las actuaciones de seguridad interior: observación de los internos, recuentos, registros, cacheos, requisas, controles, cambios de celda, asignación adecuada de destinos y las cautelas propias de las salidas fuera de los módulos o del establecimiento. Fíjate en lo que no aparece: la clasificación en grado es una decisión de tratamiento, no una medida de seguridad.","refs":[{"ref":"Art. 65.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Las actuaciones encaminadas a garantizar la seguridad interior de los establecimientos consistirán en la observación de los internos, los recuentos de población reclusa, los registros, los cacheos, las requisas, los controles, los cambios de celda, la asignación adecuada de destinos y las actividades y cautelas propias de las salidas tanto fuera de los módulos como fuera del establecimiento."}]},{"text":"La intensidad de estas medidas se ajusta a la peligrosidad potencial de los internos, en especial si pertenecen a grupos terroristas, de delincuencia organizada o de peligrosidad extrema, respetando siempre los principios del artículo 71; para ello la Administración puede constituir grupos especializados de funcionarios (art. 65.2 y 65.3 RP).","refs":[{"ref":"Art. 65.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"La intensidad de las medidas señaladas en el apartado anterior se ajustará a la potencial peligrosidad de los internos a que se apliquen, particularmente en los supuestos de internos pertenecientes a grupos terroristas, de delincuencia organizada o de peligrosidad extrema"},{"ref":"Art. 65.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Al fin señalado en el apartado anterior, la Administración penitenciaria podrá constituir grupos especializados de funcionarios."}]}]},{"n":"4","title":"Medidas preventivas: la observación de los internos","blocks":[{"text":"La observación busca conocer el comportamiento habitual del interno, sus actividades y movimientos dentro y fuera de su departamento, sus relaciones con los demás y la influencia, buena o mala, que ejerce sobre ellos. Si se detectan hechos relevantes para la seguridad o para el tratamiento, se elevan los oportunos informes (art. 66 RP).","refs":[{"ref":"Art. 66 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"La observación de los internos estará encaminada al conocimiento de su comportamiento habitual y de sus actividades y movimientos dentro y fuera del departamento asignado, así como de sus relaciones con los demás internos y del influjo beneficioso o nocivo que, en su caso, ejercieren sobre los mismos. Si en dicha observación se detectaran hechos o circunstancias que pudieran ser relevantes para la seguridad del Establecimiento o el tratamiento de los internos, se elevarán los oportunos informes."}]},{"text":"El RP de 1981, en los artículos que siguen vigentes sobre unidades de servicio, concreta esta tarea para el funcionario de patio: controlar a los internos y conocer su contingente, observar su conducta, informar al superior de cualquier novedad y practicar los cacheos, requisas y registros necesarios o que se le ordenen (art. 308.2 RP81).","refs":[{"ref":"Art. 308.2 RP81","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"a) Controlar a los internos que permanezcan en el mismo, conociendo en todo momento su contingente."},{"ref":"Art. 308.2 RP81","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"c) Observar la conducta de los internos, procurando conocerlas personalmente y, dentro de sus atribuciones, atender o cursar sus peticiones. d) Informar al superior jerárquico de cualquier novedad que se produzca"},{"ref":"Art. 308.2 RP81","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"f) Practicar los cacheos, requisas y registros que estime necesarios o que se le ordenen, con el fin de lograr un mejor control y seguridad de la Unidad."}]}]},{"n":"5","title":"Medidas de control: los recuentos","blocks":[{"text":"Los recuentos ordinarios se hacen a diario en los momentos de la jornada que coinciden con los relevos del personal de vigilancia, fijados en el horario aprobado por el Consejo de Dirección (art. 67.1 RP). Los extraordinarios los ordena el Jefe de Servicios, que lo comunica a la Dirección, teniendo en cuenta la situación del centro o departamento y el comportamiento de los internos afectados (art. 67.2 RP).","refs":[{"ref":"Art. 67.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Se realizarán diariamente los recuentos ordinarios de control de la población reclusa en los momentos de la jornada regimental que coincidan con los relevos del personal de vigilancia, que se fijen en el horario aprobado por el Consejo de Dirección del Establecimiento penitenciario."},{"ref":"Art. 67.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"También se efectuarán los recuentos extraordinarios que se ordenen por el Jefe de Servicios, comunicándolo a la Dirección"}]},{"text":"Todo recuento, ordinario o extraordinario, debe ser rápido y fiable, y su resultado se refleja en un parte escrito firmado por los funcionarios que lo hicieron y dirigido al Jefe de Servicios (art. 67.3 RP).","refs":[{"ref":"Art. 67.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los recuentos ordinarios y extraordinarios se practicarán de forma que se garantice su rapidez y fiabilidad y sus resultados se reflejarán en parte escrito suscrito por los funcionarios que los hubiesen efectuado, que se dirigirá al Jefe de Servicios."}]}]},{"n":"6","title":"Registros, cacheos y requisas","blocks":[{"text":"Se registran y cachean las personas, ropas y enseres de los internos, y se hacen requisas de puertas, ventanas, suelos, paredes y techos de celdas y dormitorios y de los locales comunes (art. 68.1 RP). De todo ello se hace parte escrito, que debe especificar los cacheos con desnudo integral, firmado por los funcionarios actuantes y dirigido al Jefe de Servicios (art. 68.5 RP).","refs":[{"ref":"Art. 68.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Se llevarán a cabo registros y cacheos de las personas, ropas y enseres de los internos y requisas de las puertas, ventanas, suelos, paredes y techos de las celdas o dormitorios, así como de los locales y dependencias de uso común."},{"ref":"Art. 68.5 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"se formulará parte escrito, que deberá especificar los cacheos con desnudo integral efectuados, firmado por los funcionarios que lo hayan efectuado y dirigido al Jefe de Servicios."}]},{"text":"El cacheo con desnudo integral es excepcional. Exige motivos de seguridad concretos y específicos, con razones individuales y contrastadas de que el interno oculta en su cuerpo un objeto peligroso o una sustancia que pueda dañar a las personas o alterar la seguridad o la convivencia, y requiere autorización del Jefe de Servicios (art. 68.2 RP). Lo practican funcionarios del mismo sexo que el interno, en lugar cerrado, sin otros internos presentes y preservando en lo posible la intimidad (art. 68.3 RP).","refs":[{"ref":"Art. 68.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Por motivos de seguridad concretos y específicos, cuando existan razones individuales y contrastadas que hagan pensar que el interno oculta en su cuerpo algún objeto peligroso o sustancia susceptible de causar daño a la salud o integridad física de las personas o de alterar la seguridad o convivencia ordenada del Establecimiento, se podrá realizar cacheo con desnudo integral con autorización del Jefe de Servicios."},{"ref":"Art. 68.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El cacheo con desnudo integral se efectuará por funcionarios del mismo sexo que el interno, en lugar cerrado sin la presencia de otros internos y preservando, en todo lo posible, la intimidad."}]},{"text":"Si el cacheo con desnudo integral no da resultado y la sospecha persiste, el Director puede pedir a la Autoridad judicial competente autorización para aplicar otros medios de control adecuados (art. 68.4 RP). La decisión de ir más allá ya no es administrativa, sino judicial.","refs":[{"ref":"Art. 68.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Si el resultado del cacheo con desnudo integral fuese infructuoso y persistiese la sospecha, se podrá solicitar por el Director a la Autoridad judicial competente la autorización para la aplicación de otros medios de control adecuados."}]}]},{"n":"7","title":"Otros registros, controles e intervenciones","blocks":[{"text":"También se registra y controla a las personas autorizadas a comunicar con los internos y a quienes entran a trabajar o hacer gestiones, salvo en las visitas oficiales de autoridades, así como los vehículos que entran o salen y los paquetes (art. 69 RP). Se intervienen el dinero, las alhajas y los objetos de valor no autorizados, y los objetos peligrosos o de procedencia ilícita, dejando constancia escrita de la retirada (art. 70 RP).","refs":[{"ref":"Art. 69 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Se procederá al registro y control de las personas autorizadas a comunicar con los internos, así como de quienes tengan acceso al interior de los Establecimientos para realizar algún trabajo o gestión dentro de los mismos, salvo en las visitas oficiales de las Autoridades."},{"ref":"Art. 70.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Se intervendrá el dinero, alhajas, u objetos de valor no autorizados, así como los objetos que se entiendan peligrosos para la seguridad o convivencia ordenada o de ilícita procedencia."}]},{"text":"El RP de 1981 detalla los puntos de paso. El funcionario de la unidad de acceso abre y cierra personalmente, guarda las llaves, identifica a quien entra y sale y controla los vehículos anotando matrícula y conductor (art. 305.3 RP81). El de rastrillo no abre de noche sin conocimiento y autorización del Jefe de Servicios e impide el paso de internos por rastrillos interiores sin orden escrita superior (art. 307.2 RP81).","refs":[{"ref":"Art. 305.3 RP81","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"b) Identificar a toda persona que haya de entrar en el establecimiento, comprobando la oportunidad o autorización para hacerlo, y recoger la documentación de quienes sean ajenos al mismo, conservándola en su poder hasta la salida."},{"ref":"Art. 305.3 RP81","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"d) Controlar las entradas y salidas de vehículos, anotando la matrícula y la identidad del conductor, y comprobar su contenido."},{"ref":"Art. 307.2 RP81","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Por la noche no abrirá sin previo conocimiento y autorización del Jefe de Servicios."}]}]},{"n":"8","title":"Principios generales de las medidas de seguridad","blocks":[{"text":"Todas las medidas de seguridad se rigen por los principios de necesidad y proporcionalidad y se aplican con respeto a la dignidad y a los derechos fundamentales, sobre todo las que recaen directamente sobre las personas. Si hay medios de igual eficacia, se prefieren los electrónicos (art. 71.1 RP).","refs":[{"ref":"Art. 71.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Las medidas de seguridad se regirán por los principios de necesidad y proporcionalidad y se llevarán siempre a cabo con el respeto debido a la dignidad y a los derechos fundamentales, especialmente las que se practiquen directamente sobre las personas. Ante la opción de utilizar medios de igual eficacia, se dará preferencia a los de carácter electrónico."}]},{"text":"Cuando, al aplicar cualquiera de estas medidas, los funcionarios detecten una anomalía regimental o un indicio de perturbación de la vida normal del centro, lo comunican de inmediato al Jefe de Servicios, sin perjuicio de usar, si procede, los medios coercitivos (art. 71.2 RP).","refs":[{"ref":"Art. 71.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"lo pondrán inmediatamente en conocimiento del Jefe de Servicios, sin perjuicio de que, en su caso, hagan uso de los medios coercitivos a que se refiere el artículo siguiente."}]}]},{"n":"9","title":"Medios coercitivos: supuestos y clases","blocks":[{"text":"La LOGP solo permite medios coercitivos, establecidos reglamentariamente y con autorización del Director, en tres supuestos: impedir evasiones o violencia de los internos; evitar que se dañen a sí mismos, a otras personas o a cosas; y vencer su resistencia activa o pasiva a las órdenes del personal (art. 45.1 LOGP). Nunca sirven para castigar una falta ya cometida: se dirigen exclusivamente a restablecer la normalidad y duran lo estrictamente necesario (art. 45.3 LOGP). Los funcionarios no pueden usar armas de fuego en sus funciones de vigilancia (art. 45.4 LOGP).","refs":[{"ref":"Art. 45.Uno LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"a) Para impedir actos de evasión o de violencia de los internos. b) Para evitar daños de los internos a sí mismos, a otras personas o cosas. c) Para vencer la resistencia activa o pasiva de los internos a las órdenes del personal penitenciario en el ejercicio de su cargo."},{"ref":"Art. 45.Tres LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"El uso de las medidas coercitivas estará dirigido exclusivamente al restablecimiento de la normalidad y solo subsistirá el tiempo estrictamente necesario."},{"ref":"Art. 45.Cuatro LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"En el desempeño de sus funciones de vigilancia los funcionarios de instituciones penitenciarias no podrán utilizar armas de fuego."}]},{"text":"El RP enumera cinco medios coercitivos: aislamiento provisional, fuerza física personal, defensas de goma, aerosoles de acción adecuada y esposas. Su uso debe ser proporcional, nunca una sanción encubierta, y solo cuando no haya otra manera menos gravosa y por el tiempo estrictamente necesario (art. 72.1 RP). Ojo: el aislamiento provisional es un medio coercitivo; el aislamiento en celda es una sanción disciplinaria distinta.","refs":[{"ref":"Art. 72.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Son medios coercitivos, a los efectos del artículo 45.1 de la Ley Orgánica General Penitenciaria, el aislamiento provisional, la fuerza física personal, las defensas de goma, los aerosoles de acción adecuada y las esposas. Su uso será proporcional al fin pretendido, nunca supondrá una sanción encubierta, y sólo se aplicarán cuando no exista otra manera menos gravosa para conseguir la finalidad perseguida y por el tiempo estrictamente necesario."}]},{"text":"No se aplican a las internas gestantes, a las que estén en los seis meses siguientes al embarazo, a las lactantes ni a las que tengan hijos consigo (las del art. 254.3 RP), ni a los convalecientes de enfermedad grave, salvo peligro inminente para su integridad o la de otros. Durante el aislamiento provisional, el Médico visita al interno a diario (art. 72.2 RP).","refs":[{"ref":"Art. 72.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"No podrán ser aplicados los expresados medios coercitivos a las internas mencionadas en el artículo 254.3 del presente Reglamento ni a los enfermos convalecientes de enfermedad grave, salvo en los casos en los que de la actuación de aquéllos pudiera derivarse un inminente peligro para su integridad o para la de otras personas. Cuando se aplique la medida de aislamiento provisional el interno será visitado diariamente por el Médico."},{"ref":"Art. 254.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"No se aplicará esta sanción a las mujeres gestantes y a las mujeres hasta seis meses después de la terminación del embarazo, a las madres lactantes y a las que tuvieran hijos consigo."}]}]},{"n":"10","title":"Medios coercitivos: autorización, comunicación y auxilio exterior","blocks":[{"text":"El uso de medios coercitivos lo autoriza previamente el Director; si la urgencia no lo permite, se le comunica inmediatamente. El Director, a su vez, comunica de inmediato al Juez de Vigilancia la adopción y el cese de la medida, detallando los hechos y las circunstancias que aconsejen mantenerla (art. 72.3 RP; art. 45.2 LOGP). Los medios materiales se depositan donde el Director considere idóneo, y su cuantía y estado constan en libro oficial (art. 72.4 RP).","refs":[{"ref":"Art. 72.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"La utilización de los medios coercitivos será previamente autorizada por el Director, salvo que razones de urgencia no lo permitan, en cuyo caso se pondrá en su conocimiento inmediatamente. El Director comunicará inmediatamente al Juez de Vigilancia la adopción y cese de los medios coercitivos"},{"ref":"Art. 45.Dos LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"Cuando, ante la urgencia de la situación, se tuviere que hacer uso de tales medios se comunicará inmediatamente al director, el cual lo pondrá en conocimiento del Juez de Vigilancia."},{"ref":"Art. 72.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los medios materiales coercitivos serán depositados en aquel lugar o lugares que el Director entienda idóneos, y su cuantía y estado se reflejará en libro oficial."}]},{"text":"Ante graves alteraciones del orden con peligro inminente para personas o instalaciones, el Director puede recabar provisionalmente el auxilio de las Fuerzas de Seguridad de guardia, que, si tienen que usar armas de fuego, lo harán con los motivos y límites de su propia legislación (art. 72.5 RP).","refs":[{"ref":"Art. 72.5 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"En los casos de graves alteraciones del orden con peligro inminente para las personas o para las instalaciones, el Director con carácter provisional podrá recabar el auxilio de las Fuerzas de Seguridad de guardia en el Establecimiento"}]}]},{"n":"11","title":"Limitaciones regimentales y medidas de protección personal","blocks":[{"text":"Los internos no soportan más limitaciones regimentales que las que exijan el aseguramiento de su persona, la seguridad y el buen orden, su tratamiento o su grado (art. 75.1 RP). Para salvaguardar la vida o la integridad física de un recluso, el Director puede acordar, a petición de este o de oficio, por resolución motivada, medidas que impliquen limitaciones regimentales, dando cuenta al Juez de Vigilancia (art. 75.2 RP).","refs":[{"ref":"Art. 75.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los detenidos, presos y penados no tendrán otras limitaciones regimentales que las exigidas por el aseguramiento de su persona y por la seguridad y el buen orden de los Establecimientos, así como las que aconseje su tratamiento o las que provengan de su grado de clasificación."},{"ref":"Art. 75.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"a solicitud del interno o por propia iniciativa, el Director podrá acordar mediante resolución motivada, cuando fuere preciso para salvaguardar la vida o integridad física del recluso, la adopción de medidas que impliquen limitaciones regimentales, dando cuenta al Juez de Vigilancia."}]},{"text":"Para poder levantar esas limitaciones, se propone al Centro Directivo el traslado a otro establecimiento de características similares: lo propone, por acuerdo motivado, el Consejo de Dirección si se trata de detenidos y presos, o la Junta de Tratamiento si son penados. El acuerdo de traslado se comunica a la autoridad judicial de la que dependan o al Juez de Vigilancia (art. 75.3 y 75.4 RP).","refs":[{"ref":"Art. 75.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Mediante acuerdo motivado, el Consejo de Dirección, en el caso de los detenidos y presos, o la Junta de Tratamiento, en el caso de penados, propondrán al Centro Directivo el traslado del recluso a otro Establecimiento de similares características"},{"ref":"Art. 75.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los acuerdos de traslado se comunicarán, en el caso de los detenidos y presos, a la Autoridad judicial de que dependan y, en el caso de los penados, al Juez de Vigilancia correspondiente."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Seguridad exterior: Fuerzas y Cuerpos de Seguridad del Estado o policías autonómicas, que reciben indicaciones del Director (art. 63.1 RP).","refs":[{"ref":"Art. 63.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"recibirán indicaciones de los Directores de los mismos."}]},{"text":"Seguridad interior: funcionarios de Instituciones Penitenciarias, según la distribución de servicios del Director (art. 64 RP).","refs":[{"ref":"Art. 64 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"con arreglo a los cometidos propios de cada uno y a la distribución de los servicios acordada por el Director del Establecimiento."}]},{"text":"Recuentos ordinarios: en los relevos del personal de vigilancia; extraordinarios: los ordena el Jefe de Servicios; parte escrito al Jefe de Servicios (art. 67 RP).","refs":[{"ref":"Art. 67.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"También se efectuarán los recuentos extraordinarios que se ordenen por el Jefe de Servicios"}]},{"text":"Desnudo integral: autoriza el Jefe de Servicios; mismo sexo, lugar cerrado; si es infructuoso, el Director pide autorización judicial para otros medios (art. 68 RP).","refs":[{"ref":"Art. 68.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"se podrá realizar cacheo con desnudo integral con autorización del Jefe de Servicios."}]},{"text":"Necesidad y proporcionalidad; a igual eficacia, medios electrónicos (art. 71.1 RP).","refs":[{"ref":"Art. 71.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Ante la opción de utilizar medios de igual eficacia, se dará preferencia a los de carácter electrónico."}]},{"text":"Cinco medios coercitivos: aislamiento provisional, fuerza física, defensas de goma, aerosoles y esposas (art. 72.1 RP).","refs":[{"ref":"Art. 72.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"el aislamiento provisional, la fuerza física personal, las defensas de goma, los aerosoles de acción adecuada y las esposas."}]},{"text":"Aislamiento provisional: visita diaria del Médico (art. 72.2 RP); adopción y cese, comunicados de inmediato al Juez de Vigilancia (art. 72.3 RP).","refs":[{"ref":"Art. 72.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Cuando se aplique la medida de aislamiento provisional el interno será visitado diariamente por el Médico."}]},{"text":"Los funcionarios no usan armas de fuego en la vigilancia (art. 45.4 LOGP).","refs":[{"ref":"Art. 45.Cuatro LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"los funcionarios de instituciones penitenciarias no podrán utilizar armas de fuego."}]},{"text":"Protección personal: la acuerda el Director y da cuenta al Juez de Vigilancia; el traslado para levantarla lo propone la Junta de Tratamiento (penados) o el Consejo de Dirección (preventivos) (art. 75 RP).","refs":[{"ref":"Art. 75.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"el Consejo de Dirección, en el caso de los detenidos y presos, o la Junta de Tratamiento, en el caso de penados"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', null, null, null, null
  from public.topics t where t.slug = 'iipp-c06-seguridad-medios-coercitivos'
