insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 190/1996, de 9 de febrero, por el que se aprueba el Reglamento Penitenciario (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('iipp-c17-modelo-organizativo', 'Derecho Penitenciario, tema 17. El modelo organizativo: órganos colegiados y unipersonales') on conflict (slug) do nothing;
