insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 1201/1981, de 8 de mayo, Reglamento Penitenciario (artículos vigentes) (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('iipp-c19-oficina-servicio-interior', 'Derecho Penitenciario, tema 19. Régimen administrativo (2): oficina de servicio interior, partes, rastrillo, comunicaciones, ingresos y paquetes') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c19-oficina-servicio-interior' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"La oficina de servicio interior y los Jefes de Centro (RP 1981, art. 303)"},{"n":"2","title":"Unidades de acceso, rastrillo, patios y galerías (arts. 305-310)"},{"n":"3","title":"Partes de servicio y comunicaciones (arts. 317-323)"},{"n":"4","title":"Ingresos y paquetes"}]'::jsonb, '["Art. 339 RP 1981: «Los partes de recuento de la población interna, en los que se recogerán los parciales presentados por los funcionarios de los distintos departamentos.»","Art. 339 RP 1981: «a) El de incidencias, en que harán constar las que por su interés aconsejen su anotación.»","Art. 339 RP 1981: «El de órdenes de la Dirección, donde se transcribirán íntegramente las que se reciban.»","Art. 303 RP 1981: «Controlar los desplazamientos de internos de unas dependencias a otras, cuidando que se mantenga adecuadamente la clasificación interior.»","Art. 305 RP 1981: «Serán consideradas unidades de acceso la puerta principal y cualquier otra entrada de personas o vehículos al interior del establecimiento.»","Art. 305 RP 1981: «recoger la documentación de quienes sean ajenos al mismo, conservándola en su poder hasta la salida.»","Art. 305 RP 1981: «Controlar las entradas y salidas de vehículos, anotando la matrícula y la identidad del conductor, y comprobar su contenido.»","Art. 307 RP 1981: «Por la noche no abrirá sin previo conocimiento y autorización del Jefe de Servicios.»","Art. 307 RP 1981: «Impedir, cuando se trate de rastrillos interiores, el paso de los internos, salvo cuando exista orden escrita superior, exigiendo la firma del funcionario que se haga cargo de los mismos.»","Art. 307 RP 1981: «Las Unidades de servicio de rastrillo estarán integradas por uno o dos de éstos cuando se hallen en proximidad inmediata, y por los locales o dependencias anejos, constituyendo un punto de paso.»","Art. 308 RP 1981: «Controlar a los internos que permanezcan en el mismo, conociendo en todo momento su contingente.»","Art. 309 RP 1981: «Comunicar al superior inmediato, mediante el correspondiente parte por escrito, cualquier incidencia o irregularidad ocurrida»","Art. 310 RP 1981: «Conservar en su poder las llaves correspondientes, practicando personalmente las operaciones de apertura y cierre de puertas.»","Art. 312 RP 1981: «Impedir que se extraigan medicamentos, comidas, ropas u otros efectos, o que sean facilitados a los enfermos sin autorización del facultativo.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Las oficinas del establecimiento y la Oficina de Servicio Interior","blocks":[{"text":"El Reglamento Penitenciario de 1981 sigue vigente, con rango de resolución del centro directivo, en los artículos que regulan las unidades de servicio y las oficinas (arts. 277-324 y 334-343 RP 1981). El artículo 334 enumera nueve oficinas: Dirección, Régimen, Equipos de Observación y Tratamiento, Administración, Servicio Interior, Identificación, Servicios Sanitarios, Instrucción y Educación y Economato Administrativo. La Oficina de Servicio Interior es la que redacta y cursa al Director los partes reglamentarios y lleva los libros y ficheros necesarios para el servicio. No debe confundirse con la Oficina de Régimen, que lleva la documentación de la población interna.","refs":[{"ref":"Art. 334 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"5.ª Oficina de Servicio Interior, en la que se redactarán y cursarán los partes reglamentarios al Director y en la que se llevarán los libros y ficheros necesarios para el mejor desempeño del servicio."},{"ref":"Art. 334 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"2.ª Oficina de Régimen, en la que se formalizará cuanto se refiere a la población interna: expedientes personales y de libertad condicional, libros, fichas y estadística."}]},{"text":"En concreto, la Oficina de Servicio Interior formula para su entrega al Director dos tipos de partes (art. 339.1 RP 1981): los partes de recuento de la población interna, que recogen los parciales presentados por los funcionarios de los distintos departamentos, y los partes de requisa y enseres, tanto los ordinarios como los extraordinarios y los que haya que promover por novedades de la guardia.","refs":[{"ref":"Art. 339.1 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"La Oficina de Servicio Interior formulará, para su entrega al Director: 1.º Los partes de recuento de la población interna, en los que se recogerán los parciales presentados por los funcionarios de los distintos departamentos. 2.º Los partes de requisa y enseres que normalmente o de modo extraordinario se efectúen y los que se deban promover por novedades ocurridas durante la guardia."}]}]},{"n":"2","title":"Los libros de la Jefatura de Servicios y el papel de los Jefes de Servicios y de Centro","blocks":[{"text":"Las Jefaturas de Servicios, o las de Centro en su caso, llevan seis libros (art. 339.2 RP 1981): el de incidencias, donde se anotan las que por su interés lo aconsejen; el de estado de conservación de instalaciones y dependencias, con los desperfectos, sus fechas y las de reparación; el de recompensas y castigos; el de órdenes de la Dirección, en el que las órdenes recibidas se transcriben íntegramente; el de instancias de internos a las Autoridades; y el de depósito de objetos y pertenencias. El libro de ingresos y filiaciones no es de la Jefatura: lo lleva la Oficina de Régimen (art. 336 RP 1981).","refs":[{"ref":"Art. 339.2 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"a) El de incidencias, en que harán constar las que por su interés aconsejen su anotación."},{"ref":"Art. 339.2 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"c) El de recompensas y castigos, en los que constarán las fechas, nombres y cuantos datos sean precisos para mejor conocimiento de los mismos. d) El de órdenes de la Dirección, donde se transcribirán íntegramente las que se reciban."},{"ref":"Art. 336 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"1.º El libro de ingresos y filiaciones, ajustado al modelo oficial."}]},{"text":"En el libro de instancias consta el número de orden, la fecha, el nombre del remitente, la Autoridad destinataria y un extracto del contenido; a cada interno se le entrega un recibo por cada instancia, y el Jefe de Servicios entrega en Dirección todas las presentadas durante su guardia (art. 339.2.e RP 1981). En el libro de depósito de objetos y pertenencias constan el nombre del depositante, el número de resguardo y los datos para identificar los objetos.","refs":[{"ref":"Art. 339.2.e RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"A cada interno se le entregará un recibo por cada instancia. El Jefe de Servicios, a su vez, entregará en Dirección el total de las instancias presentadas durante su guardia, que serán recepcionadas por el titular, quien estampará su firma en el citado libro."},{"ref":"Art. 339.2.f RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"f) El de depósito de objetos y pertenencias, que han de ser guardados en lugar seguro, donde constará, además del nombre del depositado y el número de resguardo, los datos imprescindibles para identificarlos."}]},{"text":"El Jefe de Servicios despacha a diario con el Director, cuida de la disciplina general, comprueba que sus funcionarios hagan recuentos, cacheos y requisas y dirige la oficina de la Jefatura de Servicios (art. 287.2 RP 1981). Los Jefes de Centro controlan los desplazamientos de internos entre dependencias, cuidando la clasificación interior, y llevan la documentación, libros y ficheros de la oficina de Jefatura, así como los partes de recuento, requisas y cacheos (art. 303 RP 1981).","refs":[{"ref":"Art. 287.2 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"9.ª Comprobar que los funcionarios que de él dependan realicen los recuentos, cacheos y requisas, así como las revistas e instalaciones, utensilio, vestuario y aseo de la población reclusa. 10. Dirigir la oficina de la Jefatura de Servicios y activar sus trabajos."},{"ref":"Art. 303 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"1.ª Controlar los desplazamientos de internos de unas dependencias a otras, cuidando que se mantenga adecuadamente la clasificación interior. 2.ª Llevar la documentación, libros y ficheros de la oficina de Jefatura de Servicios, así como los partes de recuento, requisas y cacheos."}]}]},{"n":"3","title":"Redacción de partes: recuento, registros e incidencias","blocks":[{"text":"El parte es el documento escrito con el que el funcionario deja constancia de un hecho del servicio y lo eleva a su superior. El RP de 1996 exige recuentos ordinarios diarios, coincidiendo con los relevos del personal de vigilancia según el horario aprobado por el Consejo de Dirección, y recuentos extraordinarios cuando los ordene el Jefe de Servicios, que lo comunica a la Dirección (art. 67 RP). Sus resultados se reflejan en parte escrito, suscrito por los funcionarios que los han hecho y dirigido al Jefe de Servicios (art. 67.3 RP).","refs":[{"ref":"Art. 67.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Se realizarán diariamente los recuentos ordinarios de control de la población reclusa en los momentos de la jornada regimental que coincidan con los relevos del personal de vigilancia, que se fijen en el horario aprobado por el Consejo de Dirección del Establecimiento penitenciario."},{"ref":"Art. 67.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los recuentos ordinarios y extraordinarios se practicarán de forma que se garantice su rapidez y fiabilidad y sus resultados se reflejarán en parte escrito suscrito por los funcionarios que los hubiesen efectuado, que se dirigirá al Jefe de Servicios."}]},{"text":"Igualmente, de los registros, requisas, cacheos y controles se formula parte escrito, que debe especificar los cacheos con desnudo integral practicados, firmado por los funcionarios que los han hecho y dirigido al Jefe de Servicios (art. 68.5 RP). Si con ocasión de cualquier medida de seguridad se detecta una anomalía regimental o un indicio de perturbación de la vida normal del centro, se pone inmediatamente en conocimiento del Jefe de Servicios (art. 71.2 RP). En las galerías, el encargado comunica al superior inmediato cualquier incidencia mediante parte por escrito y deja constancia escrita del movimiento de internos para el funcionario de relevo (art. 309.3.f RP 1981).","refs":[{"ref":"Art. 68.5 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"De los registros, requisas, cacheos y controles citados se formulará parte escrito, que deberá especificar los cacheos con desnudo integral efectuados, firmado por los funcionarios que lo hayan efectuado y dirigido al Jefe de Servicios."},{"ref":"Art. 71.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"lo pondrán inmediatamente en conocimiento del Jefe de Servicios, sin perjuicio de que, en su caso, hagan uso de los medios coercitivos a que se refiere el artículo siguiente."},{"ref":"Art. 309.3.f RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Comunicar al superior inmediato, mediante el correspondiente parte por escrito, cualquier incidencia o irregularidad ocurrida, así como dejar constancia escrita del movimiento de internos y de las incidencias del servicio para conocimiento del funcionario de relevo."}]}]},{"n":"4","title":"El parte disciplinario","blocks":[{"text":"El parte disciplinario es la vía habitual por la que el Director conoce una posible infracción: el Director acuerda de oficio y motivadamente iniciar el procedimiento sancionador por propia iniciativa cuando conoce los hechos a través de parte de funcionario informado por el Jefe de Servicios o por cualquier otro medio (art. 241.1.a RP). En el procedimiento abreviado para faltas leves, el parte del funcionario opera como pliego de cargos: se comunica al Jefe de Servicios y, a la vez, se notifica al presunto infractor; ambos disponen de diez días para alegaciones y pruebas, y el procedimiento debe resolverse en un mes como máximo (art. 251 RP). Las fuentes oficiales disponibles no contienen un modelo oficial de redacción de partes; aquí solo se recogen los requisitos que fijan los reglamentos.","refs":[{"ref":"Art. 241.1.a RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Por propia iniciativa, cuando tenga conocimiento de la existencia de conductas o hechos susceptibles de constituir infracción disciplinaria a través de parte de funcionario informado por el Jefe de Servicios o por cualquier otro medio."},{"ref":"Art. 251.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"deberá resolverse en el plazo máximo de un mes desde que se inició, con arreglo a las siguientes normas: a) El parte del funcionario, que operará como pliego de cargos, se comunicará al Jefe de Servicios y, simultáneamente, se notificará al presunto infractor. b) En el plazo de diez días"}]}]},{"n":"5","title":"Unidad de acceso","blocks":[{"text":"Son unidades de acceso la puerta principal y cualquier otra entrada de personas o vehículos al interior del establecimiento, junto con sus locales anejos (art. 305 RP 1981). El funcionario encargado abre y cierra personalmente, conserva siempre las llaves y, al terminar la jornada, las entrega al Jefe de la Guardia exterior o al Jefe de Servicios. Identifica a toda persona que entra, comprueba su autorización y recoge la documentación de los ajenos al centro, que conserva hasta la salida. A la salida identifica a quien sale, devuelve los documentos y, si salen internos, firma y diligencia las órdenes de salida (libertad, diligencias, trabajos en el exterior o conducción). También controla los vehículos, anotando matrícula e identidad del conductor y comprobando su contenido, y evita que se formen grupos junto a la puerta.","refs":[{"ref":"Art. 305.1 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Serán consideradas unidades de acceso la puerta principal y cualquier otra entrada de personas o vehículos al interior del establecimiento."},{"ref":"Art. 305.3.b RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Identificar a toda persona que haya de entrar en el establecimiento, comprobando la oportunidad o autorización para hacerlo, y recoger la documentación de quienes sean ajenos al mismo, conservándola en su poder hasta la salida."},{"ref":"Art. 305.3.d RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Controlar las entradas y salidas de vehículos, anotando la matrícula y la identidad del conductor, y comprobar su contenido."}]},{"text":"Cuando el movimiento de vehículos o la carga lo aconsejen, el Director puede ordenar que uno o varios funcionarios acompañen a los vehículos desde la puerta hasta el lugar de descarga, o desde la carga hasta la salida; esos funcionarios responden de que no entre ni salga ningún interno ni objeto indebido y entregan justificante escrito al funcionario de la puerta (art. 306 RP 1981).","refs":[{"ref":"Art. 306 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"los funcionarios designados serán responsables de que no entre ni salga ningún interno ni objeto que no deba hacerlo, entregando justificante escrito al funcionario de la puerta."}]}]},{"n":"6","title":"Unidad de rastrillo","blocks":[{"text":"La unidad de rastrillo está integrada por uno o dos rastrillos cuando están en proximidad inmediata y por sus locales anejos, y constituye un punto de paso (art. 307.1 RP 1981). Su encargado abre y cierra personalmente y conserva las llaves durante el servicio; por la noche no abre sin previo conocimiento y autorización del Jefe de Servicios. Cuida de que solo pasen los funcionarios de la plantilla y las personas autorizadas. En los rastrillos interiores impide el paso de internos salvo orden escrita superior, y exige la firma del funcionario que se hace cargo de ellos. Además identifica individualmente o constata numéricamente el contingente de internos, anotando la hora del movimiento y diligencia las órdenes de libertad, traslados o salidas.","refs":[{"ref":"Art. 307.1 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Las Unidades de servicio de rastrillo estarán integradas por uno o dos de éstos cuando se hallen en proximidad inmediata, y por los locales o dependencias anejos, constituyendo un punto de paso."},{"ref":"Art. 307.2.a RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Por la noche no abrirá sin previo conocimiento y autorización del Jefe de Servicios."},{"ref":"Art. 307.2.c RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Impedir, cuando se trate de rastrillos interiores, el paso de los internos, salvo cuando exista orden escrita superior, exigiendo la firma del funcionario que se haga cargo de los mismos."},{"ref":"Art. 307.2.d RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Identificar individualmente o constatar numéricamente el contingente de internos, con anotación de la hora en que se produce el movimiento de los mismos."}]}]},{"n":"7","title":"Patios, galerías y enfermería","blocks":[{"text":"El encargado del patio controla a los internos que permanecen en él, conociendo en todo momento su contingente; impide entradas y salidas no autorizadas y practica cacheos, requisas y registros (art. 308 RP 1981). El encargado de galería lleva una relación actualizada de los internos con su celda, autoriza por orden escrita las salidas y diligencia las entradas (art. 309.3 RP 1981). Los funcionarios que dependen de él conservan las llaves y practican personalmente la apertura y cierre de puertas (art. 310 RP 1981).","refs":[{"ref":"Art. 308.2.a RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Controlar a los internos que permanezcan en el mismo, conociendo en todo momento su contingente."},{"ref":"Art. 309.3 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"a) Llevar relación actualizada de los internos albergados en la Unidad, con anotación de la celda o puesto ocupado y de las circunstancias regimentales que a ellos se refieran."},{"ref":"Art. 309.3.c RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Autorizar mediante la correspondiente orden escrita las salidas de internos y diligenciar las entradas de éstos en la Unidad."},{"ref":"Art. 310.b RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Conservar en su poder las llaves correspondientes, practicando personalmente las operaciones de apertura y cierre de puertas."}]},{"text":"El funcionario de enfermería tiene las obligaciones del encargado de galería y, además, impide que se extraigan medicamentos, comidas, ropas u otros efectos o que se faciliten a los enfermos sin autorización del facultativo (art. 312 RP 1981).","refs":[{"ref":"Art. 312.c RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Impedir que se extraigan medicamentos, comidas, ropas u otros efectos, o que sean facilitados a los enfermos sin autorización del facultativo."}]}]},{"n":"8","title":"Unidad de comunicaciones y visitas e información al exterior","blocks":[{"text":"El servicio de comunicaciones orales y escritas es una unidad a cargo de un funcionario, que vela por el cumplimiento de las normas y órdenes de la Dirección, lleva actualizada la documentación del servicio, cuida del orden y atiende a los visitantes (art. 316 RP 1981). Confecciona las relaciones de personas que solicitan comunicar y comprueba que reúnen las condiciones, organiza la entrada de visitantes con su identificación y la recogida y devolución de documentos, vigila las comunicaciones, las interviene cuando proceda y, si procede suspenderlas, propone la suspensión al Jefe de Servicios: no la acuerda él (art. 317 RP 1981).","refs":[{"ref":"Art. 317 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"a) Confeccionar las relaciones de personas que soliciten comunicar, comprobando que reúnen las condiciones para poder hacerlo. b) Organizar y controlar la entrada de los visitantes, procediendo a su identificación y a la recogida y devolución de documentos."},{"ref":"Art. 317.c RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"proponer la suspensión al Jefe de servicios, cuando proceda con arreglo a las citadas normas."}]},{"text":"En las comunicaciones escritas recoge la correspondencia depositada por los internos, rechazando la que no proceda, conoce el contenido de los escritos cuando la ley lo permite, anota en los libros de registro toda la correspondencia que expiden o reciben los internos y la entrega personalmente a los destinatarios tras comprobar que no contiene objetos no autorizados (art. 318 RP 1981). Por su parte, el servicio de información al exterior lleva un fichero, actualizado a diario, de todos los internos presentes, con fecha de ingreso y departamento, e informa a los familiares de los días y horas de comunicación y de recepción de paquetes y dinero (art. 323 RP 1981).","refs":[{"ref":"Art. 318.c RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Anotar en los libros de registro toda la correspondencia que expidan o reciban los internos."},{"ref":"Art. 323.a RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Llevar, actualizándolo diariamente, un fichero de todos los internos presentes en el Establecimiento, en el que constará la fecha de ingreso, el departamento donde están clasificados"},{"ref":"Art. 323.b RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Informar a los familiares sobre los extremos contenidos en el número anterior, así como de los días y horas de comunicación y de recepción de paquetes y dinero."}]}]},{"n":"9","title":"Unidad de ingresos y salidas","blocks":[{"text":"La unidad de ingresos y salidas comprende los locales donde permanecen los internos al ingresar o salir para registrarlos a ellos y sus enseres, recoger el dinero, valores, joyas, documentación y objetos no autorizados, o devolverlos a la salida (art. 319.1 RP 1981). Su encargado se hace cargo de los internos que ingresan, previa comprobación por el funcionario designado de la documentación que porta la fuerza pública, y los distribuye en celdas siguiendo en lo posible la clasificación. Hace el registro personal y de ropas y equipaje, y recoge el dinero, alhajas y valores, que custodia hasta entregarlos al Administrador, dando al interno un recibo provisional que se canjea por el definitivo que extiende este. También informa al Jefe de Servicios de cualquier anomalía.","refs":[{"ref":"Art. 319.2.a RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Hacerse cargo de los internos que ingresen, previa comprobación por el funcionario designado para ello de la documentación de que sea portadora la Fuerza pública"},{"ref":"Art. 319.2.c RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Recoger a los ingresados el dinero, alhajas y valores, y custodiarlos hasta que haga su entrega al Administrador, facilitando a los internos el recibo provisional que será canjeado por el definitivo que extienda éste."},{"ref":"Art. 319.2.j RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Informar al Jefe de Servicios de cualquier anomalía que observe y de cualquier incidencia que ocurra en el desarrollo de este servicio."}]},{"text":"El RP de 1996 completa el trámite: al admitir a un recluso se verifica su identidad con la reseña alfabética, dactilar y fotográfica, se inscribe en el libro de ingresos, se abre su expediente personal y se practica el cacheo de su persona y el registro de sus efectos (art. 18.1 RP). En la salida por libertad, el funcionario encargado, o el que designe el Jefe de Servicios, identifica al liberado cotejando las huellas dactilares y los datos de filiación y lo acompaña hasta la salida (art. 22.4 RP).","refs":[{"ref":"Art. 18.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"se procederá a verificar su identidad personal, efectuando la reseña alfabética, dactilar y fotográfica, así como a la inscripción en el libro de ingresos y la apertura de un expediente personal"},{"ref":"Art. 22.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El funcionario encargado del servicio o, en su defecto, el que designe el Jefe de Servicios procederá a realizar la identificación de quien haya de ser liberado, cotejando las huellas dactilares y comprobando los datos de filiación, y le acompañará, posteriormente, hasta la salida del centro penitenciario."}]}]},{"n":"10","title":"Recepción y salida de paquetes y encargos","blocks":[{"text":"La unidad de paquetes y encargos comprende las ventanillas al público y los almacenes donde se registran y guardan los envíos (art. 320 RP 1981). Su encargado lleva la relación actualizada de internos con su departamento, organiza la recogida en ventanilla anotando en los libros el nombre del destinatario y el nombre, domicilio y número del documento de identidad de quien entrega, pide una relación detallada del contenido para rechazar en el acto lo no autorizado, registra minuciosamente todos los paquetes y entrega los recibidos a los internos, que firman en el libro correspondiente.","refs":[{"ref":"Art. 320.2.b RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Organizar la recogida de paquetes en las ventanillas del público, anotando en los libros el nombre del destinatario, y el nombre, domicilio y número del documento de identidad de quien los entrega."},{"ref":"Art. 320.2.f RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Hacer entrega de los paquetes recibidos a los internos a quienes vengan destinados, cuidando de que firmen en el libro correspondiente, donde constará el nombre del remitente."}]},{"text":"Según el RP de 1996, el Consejo de Dirección fija los días y horas de recepción y recogida, y los paquetes se entregan personalmente en la dependencia habilitada (art. 50 RP). Cada interno puede recibir dos paquetes al mes, o uno en régimen cerrado, de no más de cinco kilos, sin contar libros, publicaciones ni ropa. Los objetos no autorizados debe retirarlos el remitente; pasados tres meses se publica una relación en el tablón y, quince días después, se destruyen, salvo los objetos de valor (art. 51 RP).","refs":[{"ref":"Art. 50.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El Consejo de Dirección acordará los días y horas de recepción y recogida de paquetes, tanto de entrada como de salida."},{"ref":"Art. 50.5 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El número de paquetes que pueden recibir los internos es de dos al mes, salvo en los Establecimientos o departamentos de régimen cerrado, que será de uno al mes. El peso de cada paquete no excederá de cinco kilogramos, no computándose dentro de dicho peso máximo los libros y publicaciones, ni tampoco la ropa."},{"ref":"Art. 51.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Transcurrido un plazo de tres meses desde su recepción, se colocará una relación de tales artículos u objetos en el tablón de anuncios al público"}]}]},{"n":"11","title":"La Oficina de Identificación: dactilogramas","blocks":[{"text":"La Oficina de Identificación formaliza la filiación e identificación dactiloscópica y fotográfica de los internos (art. 334 RP 1981). Sus cometidos son (art. 340 RP 1981): imprimir el pulgar derecho en el expediente a la entrada y salida del interno y en las hojas de conducción por traslado y en las licencias de cumplidos y liberados condicionales; expedir antecedentes e informes periciales de identificación que pidan los tribunales; reseñar todos los ingresos haciendo dos fichas dactilares y dos alfabéticas, salvo tránsitos, arrestos y quienes ya tengan reseña en el centro; y formar dos archivos de tarjetas dactiloscópicas, uno alfabético y otro dactilar.","refs":[{"ref":"Art. 340 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"a) La impresión dactilar del pulgar derecho en el expediente del interno a su ingreso y salida, cualquiera que sea el motivo."},{"ref":"Art. 340 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"d) Reseñar todos los ingresos, hombres o mujeres, haciendo para cada uno dos fichas dactilares y dos alfabéticas, excepto los tránsitos, los arrestos y los que a su ingreso ya tuvieren en la Oficina del establecimiento"},{"ref":"Art. 340 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"e) La formación de dos archivos de tarjetas de identificación dactiloscópica, alfabético el uno y dactilar el otro, de todos los ingresados."}]},{"text":"Del 1 al 10 de cada mes remite al centro directivo lo hecho en el mes anterior, o comunicación negativa si no hubo ingresos, con un ejemplar de cada reseña nueva formulada y con subfórmula de la mano derecha; si todos los dactilogramas son del tipo bideltos, se subformulan ambas manos. En centros con un contingente medio anual de quinientos o más reclusos hay personal nombrado específicamente para este servicio. Las fuentes disponibles no desarrollan la técnica de clasificación de los dactilogramas más allá de lo que dice este artículo.","refs":[{"ref":"Art. 340 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"f) La remisión al Centro Directivo, del 1 al 10 de cada mes, de todo lo realizado en el anterior o comunicación negativa, caso de no haber ingresos, enviando un ejemplar de cada reseña nueva, debidamente formulada y con subfórmula de la mano derecha, a excepción de aquella fórmula en la que todos los dactilogramas pertenezcan al tipo bideltos, en cuyo caso deberán subformularse ambas manos."},{"ref":"Art. 340 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"En los establecimientos penitenciarios de un contingente medio anual de quinientos o más reclusos habrá personal especialmente nombrado para el Servicio de Identificación."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"La Oficina de Servicio Interior entrega al Director los partes de recuento y los partes de requisa y enseres.","refs":[{"ref":"Art. 339.1 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Los partes de recuento de la población interna, en los que se recogerán los parciales presentados por los funcionarios de los distintos departamentos."}]},{"text":"Libros de la Jefatura: incidencias, conservación, recompensas y castigos, órdenes de la Dirección (transcritas íntegramente), instancias y depósito de objetos. El de ingresos y filiaciones es de la Oficina de Régimen.","refs":[{"ref":"Art. 339.2.d RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"d) El de órdenes de la Dirección, donde se transcribirán íntegramente las que se reciban."}]},{"text":"Los partes de recuento y de registros, cacheos y requisas van firmados por quienes los practican y dirigidos al Jefe de Servicios.","refs":[{"ref":"Art. 67.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"sus resultados se reflejarán en parte escrito suscrito por los funcionarios que los hubiesen efectuado, que se dirigirá al Jefe de Servicios."}]},{"text":"En el procedimiento abreviado, el parte del funcionario opera como pliego de cargos.","refs":[{"ref":"Art. 251.1.a RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El parte del funcionario, que operará como pliego de cargos, se comunicará al Jefe de Servicios y, simultáneamente, se notificará al presunto infractor."}]},{"text":"Acceso: documentación de los ajenos retenida hasta la salida; vehículos con matrícula e identidad del conductor.","refs":[{"ref":"Art. 305.3.d RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Controlar las entradas y salidas de vehículos, anotando la matrícula y la identidad del conductor, y comprobar su contenido."}]},{"text":"Rastrillo: de noche no se abre sin conocimiento y autorización del Jefe de Servicios; en rastrillos interiores, internos solo con orden escrita y firma del funcionario que se hace cargo.","refs":[{"ref":"Art. 307.2.a RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"Por la noche no abrirá sin previo conocimiento y autorización del Jefe de Servicios."}]},{"text":"El funcionario de comunicaciones no suspende la comunicación: propone la suspensión al Jefe de Servicios.","refs":[{"ref":"Art. 317.c RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"proponer la suspensión al Jefe de servicios, cuando proceda con arreglo a las citadas normas."}]},{"text":"Dinero y valores del ingresado: recibo provisional y entrega al Administrador, que extiende el definitivo.","refs":[{"ref":"Art. 319.2.c RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"facilitando a los internos el recibo provisional que será canjeado por el definitivo que extienda éste."}]},{"text":"Paquetes: dos al mes (uno en régimen cerrado), máximo cinco kilos sin contar libros ni ropa.","refs":[{"ref":"Art. 50.5 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El número de paquetes que pueden recibir los internos es de dos al mes, salvo en los Establecimientos o departamentos de régimen cerrado, que será de uno al mes."}]},{"text":"Identificación: pulgar derecho a la entrada y salida; dos fichas dactilares y dos alfabéticas; remisión al centro directivo del 1 al 10 de cada mes.","refs":[{"ref":"Art. 340 RP 1981","law":"RP 1981","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095","quote":"b) La impresión dactilar del pulgar derecho en las hojas de conducción por traslado a otro establecimiento y en las licencias de cumplidos y liberados condicionalmente."}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1981-14095', null, null, null, null
  from public.topics t where t.slug = 'iipp-c19-oficina-servicio-interior'
on conflict (topic_id, locale) do update
   set outline = excluded.outline, key_ideas = excluded.key_ideas, glossary = excluded.glossary,
       amendments = excluded.amendments, lessons = excluded.lessons, source_id = excluded.source_id, source_url = excluded.source_url,
       page_from = excluded.page_from, page_to = excluded.page_to, key_ideas_page = excluded.key_ideas_page
