       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Real Decreto 190/1996, de 9 de febrero, por el que se aprueba el Reglamento Penitenciario (texto consolidado, BOE)', 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', 'boe'::public.source_kind, 'Agencia Estatal Boletín Oficial del Estado', null) on conflict (url) do nothing;
insert into public.topics (slug, title) values ('iipp-c20-regimen-economico-peculio', 'Derecho Penitenciario, tema 20. Régimen económico: peculio, pertenencias, economato, almacenes y habilitación') on conflict (slug) do nothing;
insert into public.exam_body_topics (exam_body_id, topic_id) select b.id, t.id from public.exam_bodies b, public.topics t where b.slug in ('ayudantes-instituciones-penitenciarias') and t.slug = 'iipp-c20-regimen-economico-peculio' on conflict do nothing;
insert into public.topic_notes as n (topic_id, locale, outline, key_ideas, glossary, amendments, lessons, source_id, source_url, page_from, page_to, key_ideas_page, review_note)
select t.id, 'es', '[{"n":"1","title":"Régimen económico de los establecimientos (arts. 293-310 RP)"},{"n":"2","title":"Peculio de los internos"},{"n":"3","title":"Pertenencias y depósito de objetos"},{"n":"4","title":"Economato, almacenes y habilitación (arts. 300-324 RP)"}]'::jsonb, '["Art. 293.1 RP: «Los Servicios administrativos de los Establecimientos penitenciarios dependen directamente del Administrador del centro.»","Art. 293.2 RP: «Todo acto o decisión económico-administrativa de un Establecimiento penitenciario deberá estar propuesto por el Administrador y autorizado por el Director del centro»","Art. 294.1 RP: «exigiéndose, en todo caso, la firma mancomunada del Director y del Administrador del Establecimiento o, en su caso, del suplente de uno u otro.»","Art. 298 RP: «Los economatos de los Establecimientos penitenciarios son un servicio prestado por la institución penitenciaria a los internos que permite disponer de un sistema de adquisición de productos de naturaleza complementaria»","Art. 300.1 RP: «a) La propia Administración penitenciaria. b) El Organismo Autónomo Trabajo y Prestaciones Penitenciarias, mediante la fórmula de taller productivo. c) Empresas externas adjudicatarias por contrato administrativo de servicios.»","Art. 301.1 RP: «Queda prohibido a los internos el uso de dinero de curso legal, salvo en los Establecimientos de régimen abierto o en situaciones excepcionales debidamente autorizadas por el centro directivo.»","Art. 303.2 RP: «En ningún caso podrán venderse en el economato ningún tipo de bebidas alcohólicas ni de productos farmacéuticos.»","Art. 305.1 RP: «las prestaciones que deban realizar los internos en servicios auxiliares o mecánicos de los mismos no tendrán, en ningún caso, la naturaleza de relación laboral especial penitenciaria»","Art. 305.2 RP: «los servicios auxiliares o mecánicos de los mismos desempeñados por los internos tendrán la naturaleza de relación laboral especial penitenciaria.»","Art. 311 RP: «Si algún interno renunciase a su ración, quedará ésta en beneficio de los demás, no de persona determinada, sin que por tal renuncia se le deba indemnización alguna.»","Art. 313.1 RP: «La composición del vestuario se determinará por resolución del centro directivo correspondiente»","Art. 316.1 RP: «Los Establecimientos penitenciarios solicitarán mensualmente, en función de la previsión de población interna existente y de sus características personales y penitenciarias, las necesidades de dotación en lotes higiénicos.»","Art. 317 RP: «Los objetos de valor se custodiarán por el Subdirector de Seguridad en la caja del Establecimiento o en lugar seguro y el dinero será custodiado por el Administrador.»","Art. 317 RP: «Salvo en los Establecimientos de régimen abierto, los internos no tendrán en su poder dinero o títulos que lo representen ni objetos de valor.»"]'::jsonb, '[]'::jsonb, '[]'::jsonb, '[{"n":"1","title":"Principios generales de la gestión económica","blocks":[{"text":"El Título IX del Reglamento Penitenciario de 1996 regula la gestión económico-administrativa de los establecimientos. Su finalidad es optimizar los recursos financieros y materiales para que la actividad penitenciaria se cumpla de forma eficaz y eficiente (art. 288 RP). Los recursos que asignan y gestionan los establecimientos son recursos públicos, sujetos a la normativa presupuestaria, contractual, contable y patrimonial de las Administraciones Públicas (art. 292 RP). Por eso ningún establecimiento puede asumir compromisos de gasto por encima de los créditos asignados ni cambiar la imputación del gasto o su procedimiento (art. 290 RP). El Director, tras informe de la Junta Económico-Administrativa, remite a la Secretaría de Estado antes del 1 de abril de cada año la previsión de necesidades presupuestarias del ejercicio siguiente (art. 291 RP).","refs":[{"ref":"Art. 292 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los recursos económicos asignados y gestionados por los Establecimientos penitenciarios tienen la naturaleza de recursos públicos, a los que resultará de aplicación la normativa presupuestaria, contractual, contable o patrimonial vigente para las Administraciones Públicas."},{"ref":"Art. 290 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Ningún Establecimiento penitenciario podrá adoptar ninguna decisión que implique compromisos de gasto por encima de los créditos asignados al mismo"},{"ref":"Art. 291 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"antes del 1 de abril de cada año natural, la previsión de necesidades presupuestarias para el siguiente ejercicio"}]},{"text":"Los servicios administrativos dependen directamente del Administrador (art. 293.1 RP), que tiene rango de Subdirector. Como regla general, todo acto o decisión económico-administrativa debe estar propuesto por el Administrador y autorizado por el Director, salvo que el Reglamento prevea otro procedimiento (art. 293.2 RP). La Junta Económico-Administrativa, presidida por el Director y en la que el Administrador es el sustituto en la presidencia, supervisa la gestión de personal, económico-administrativa, presupuestaria y contable del centro (arts. 278 y 279 RP).","refs":[{"ref":"Art. 293 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los Servicios administrativos de los Establecimientos penitenciarios dependen directamente del Administrador del centro. 2. Todo acto o decisión económico-administrativa de un Establecimiento penitenciario deberá estar propuesto por el Administrador y autorizado por el Director del centro"},{"ref":"Art. 279 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"es el órgano colegiado encargado de la supervisión de la gestión de personal, económico-administrativa, presupuestaria y contable del Establecimiento"},{"ref":"Art. 278.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El sustituto del Director en la presidencia de la Junta Económico-Administrativa será el Administrador del centro penitenciario."}]}]},{"n":"2","title":"Contabilidad, cuentas bancarias y rendición de cuentas","blocks":[{"text":"El movimiento de fondos de las cuentas bancarias abiertas a nombre del establecimiento sigue la normativa del Tesoro y exige siempre la firma mancomunada del Director y del Administrador, o del suplente de uno u otro (art. 294.1 RP). La autorización de apertura de estas cuentas la tramita la Dirección General de Administración Penitenciaria ante el Tesoro (art. 294.2 RP). El Administrador extiende los talones junto con la firma mancomunada del Director y rinde las cuentas ante los órganos competentes con el visado del Director y el informe de la Junta Económico-Administrativa (art. 282 RP). A la Junta corresponde el seguimiento y control del sistema contable y de la ejecución presupuestaria e informar las cuentas que se rinden al centro directivo (art. 279 RP). El Director, por su parte, supervisa los libros de contabilidad y autoriza los pagos de caja y la extracción de fondos (art. 280.2.8.ª RP).","refs":[{"ref":"Art. 294.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"exigiéndose, en todo caso, la firma mancomunada del Director y del Administrador del Establecimiento o, en su caso, del suplente de uno u otro."},{"ref":"Art. 282 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"b) Extender los talones de las cuentas bancarias del centro penitenciario junto con la firma mancomunada del Director o de su suplente."},{"ref":"Art. 282 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"e) Rendir las cuentas ante los órganos competentes con el visado del Director y el informe de la Junta Económico-Administrativa."},{"ref":"Art. 279 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"b) El seguimiento y control del sistema contable. c) Informar las cuentas que se deban rendir al centro directivo."}]},{"text":"Sobre cuentas presupuestarias y extrapresupuestarias, las fuentes disponibles solo ofrecen piezas sueltas. La Ley General Presupuestaria define los anticipos de caja fija como provisiones de fondos de carácter extrapresupuestario y permanente a pagadurías, cajas y habilitaciones para atender gastos periódicos o repetitivos del capítulo de gastos corrientes (art. 78 LGP). El RP permite comprar alimentos vía pagos a justificar, anticipos de caja fija o contratos de suministro (art. 312 RP). El programa pide además la contabilidad general y la oficina de habilitación (nóminas y Seguridad Social de los empleados públicos), que no están desarrolladas en las fuentes oficiales disponibles; tampoco hay normativa específica de gestión de almacenes.","refs":[{"ref":"Art. 78.1 LGP","law":"Ley 47/2003","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2003-21614","quote":"Se entienden por anticipos de caja fija las provisiones de fondos de carácter extrapresupuestario y permanente que se realicen a pagadurías, cajas y habilitaciones para la atención inmediata y posterior aplicación al capítulo de gastos corrientes en bienes y servicios del presupuesto del año en que se realicen, de gastos periódicos o repetitivos."},{"ref":"Art. 312 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"utilizando proveedores ajenos a la propia Administración, vía pagos a justificar, anticipos de caja fija o expedientes de contratación administrativa de suministros."}]}]},{"n":"3","title":"Régimen patrimonial e inventario","blocks":[{"text":"Cada establecimiento lleva un sistema de inventarios que da información fiel y actualizada de los bienes muebles asignados; las altas y bajas se consignan mediante actas de recepción o enajenación (art. 295.1 RP). El centro directivo fija los tipos de inventario obligatorios y la documentación y periodicidad para elaborar el inventario general de bienes muebles (art. 295.2 RP). Las donaciones al establecimiento no pueden aceptarse sin autorización previa y expresa del centro directivo, y para enajenar bienes muebles el Director pide autorización a la Dirección General de Administración Penitenciaria (art. 295.3 y 4 RP).","refs":[{"ref":"Art. 295.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los Establecimientos penitenciarios llevarán un sistema de inventarios que permita disponer en todo momento de información fiel y actualizada sobre los bienes muebles asignados para el desarrollo de sus funciones."},{"ref":"Art. 295.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"que no podrán ser aceptadas sin la previa y expresa autorización del centro directivo."}]},{"text":"Si se abre o cierra un establecimiento, la gestión patrimonial parte de los inventarios de apertura o clausura firmados por el Director y el Administrador (art. 296 RP). Los establecimientos que hacen de depósito de suministros llevan un inventario especial que permite conocer la distribución a otros centros y las reservas (art. 297 RP). Los utensilios y efectos dados de baja se enajenan según normas del centro directivo, la venta consta en acta y su producto se ingresa en el Tesoro Público (art. 315 RP).","refs":[{"ref":"Art. 296 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"a partir de los respectivos inventarios de apertura o clausura firmados por el Director y Administrador del Establecimiento."},{"ref":"Art. 315 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"La venta constará en acta y su producto se ingresará en el Tesoro Público."}]}]},{"n":"4","title":"Economatos, cafeterías y cocinas: formas de gestión","blocks":[{"text":"El economato es un servicio que la institución presta a los internos para que puedan adquirir productos complementarios a los que facilita la Administración (art. 298 RP). La cafetería puede atender al personal del centro, a la guardia exterior, a quien preste algún servicio y a las visitas (art. 299 RP). Economato, cocina y cafetería pueden gestionarse de tres formas (art. 300.1 RP): por la propia Administración penitenciaria, por el organismo de trabajo penitenciario mediante la fórmula de taller productivo, o por empresas externas adjudicatarias de un contrato administrativo de servicios. El RP se refiere al «Organismo Autónomo Trabajo y Prestaciones Penitenciarias»; hoy esas funciones las ejerce la entidad estatal Trabajo Penitenciario y Formación para el Empleo, que gestiona los economatos y cafeterías (art. 3 RD 122/2015).","refs":[{"ref":"Art. 298 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los economatos de los Establecimientos penitenciarios son un servicio prestado por la institución penitenciaria a los internos que permite disponer de un sistema de adquisición de productos de naturaleza complementaria a los facilitados por la propia Administración penitenciaria."},{"ref":"Art. 300.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"a) La propia Administración penitenciaria. b) El Organismo Autónomo Trabajo y Prestaciones Penitenciarias, mediante la fórmula de taller productivo. c) Empresas externas adjudicatarias por contrato administrativo de servicios."},{"ref":"Art. 3 RD 122/2015","law":"RD 122/2015","url":"https://www.boe.es/buscar/act.php?id=BOE-A-2015-2115","quote":"b) La gestión de los economatos y cafeterías existentes en los establecimientos penitenciarios y Centros de Inserción Social"}]},{"text":"Si gestiona el organismo de trabajo, los beneficios son suyos (art. 300.2 RP). Si gestiona la Administración o una empresa externa, los beneficios para la Administración se ingresan en el Tesoro Público y vuelven, mediante generaciones de crédito, a los conceptos presupuestarios penitenciarios; en gestión directa, se entiende por beneficio lo que queda tras pagar la compra de géneros, las recompensas a internos y la depreciación de existencias (art. 300.4 RP).","refs":[{"ref":"Art. 300.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"se entenderá por beneficios los obtenidos una vez sufragados los gastos correspondientes a la compra de géneros, las recompensas a internos y la depreciación de existencias."}]}]},{"n":"5","title":"El economato: pago, productos y trabajo de los internos","blocks":[{"text":"Los internos no pueden usar dinero de curso legal, salvo en régimen abierto o en situaciones excepcionales autorizadas por el centro directivo; las compras se hacen con tarjeta-valor, tarjeta magnética, tarjeta con microchip u otro sistema análogo (art. 301.1 RP). Al ser excarcelado, salir de permiso o ser trasladado, la tarjeta se canjea por su importe en metálico (art. 301.4 RP). La lista de productos y precios se expone junto a la ventanilla (art. 302.2 RP). Se pueden vender comestibles que no necesiten cocinarse, tabaco, ropa, productos de aseo y otros no prohibidos, pero nunca bebidas alcohólicas ni productos farmacéuticos (art. 303 RP). Si un producto autorizado no está disponible, la Dirección puede autorizar su compra en el exterior a costa del interno (art. 304 RP).","refs":[{"ref":"Art. 301.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Queda prohibido a los internos el uso de dinero de curso legal, salvo en los Establecimientos de régimen abierto o en situaciones excepcionales debidamente autorizadas por el centro directivo."},{"ref":"Art. 301.4 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"se canjeará la tarjeta de compras de que sea titular por su importe en metálico."},{"ref":"Art. 303 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"a) Comestibles que no precisen ser cocinados. b) Tabaco. c) Ropa de uso interior y exterior. d) Productos de aseo personal."},{"ref":"Art. 303.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"En ningún caso podrán venderse en el economato ningún tipo de bebidas alcohólicas ni de productos farmacéuticos."}]},{"text":"La naturaleza del trabajo de los internos en estos servicios depende de la forma de gestión (art. 305 RP): en gestión directa por la Administración no es nunca relación laboral especial penitenciaria, sin perjuicio de recompensas y beneficios; si gestiona el organismo de trabajo como taller productivo, sí es relación laboral especial; y con empresa externa ningún interno puede trabajar en ellos, salvo que la oferta prevea su contratación laboral común. El interno que sustrae fondos o efectos o deteriora intencionadamente los productos es separado del servicio y responde pecuniariamente, además de la responsabilidad disciplinaria o penal (art. 306 RP).","refs":[{"ref":"Art. 305.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"las prestaciones que deban realizar los internos en servicios auxiliares o mecánicos de los mismos no tendrán, en ningún caso, la naturaleza de relación laboral especial penitenciaria"},{"ref":"Art. 305.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"los servicios auxiliares o mecánicos de los mismos desempeñados por los internos tendrán la naturaleza de relación laboral especial penitenciaria."},{"ref":"Art. 306 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"será separado de dichos servicios y se le exigirá la responsabilidad pecuniaria que proceda"}]}]},{"n":"6","title":"Cocina y alimentación","blocks":[{"text":"La LOGP obliga a proporcionar una alimentación controlada por el Médico, preparada según normas dietéticas y de higiene, que tenga en cuenta la salud, el trabajo y, en lo posible, las convicciones filosóficas y religiosas del interno (art. 21.2 LOGP). Los internos devengan la ración según su hora de ingreso y salida, sin doble imputación en los traslados (art. 307.1 RP). La Secretaría de Estado fija cada año el valor de la ración por día y plaza, distinguiendo al menos internos sanos, jóvenes y ración de enfermería (art. 308.1 RP). Los gastos de alimentación tienen un seguimiento contable especial y se elevan a la Junta Económico-Administrativa (art. 309 RP).","refs":[{"ref":"Art. 21.Dos LOGP","law":"LOGP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1979-23708","quote":"La Administración proporcionará a los internos una alimentación controlada por el Médico, convenientemente preparada y que responda en cantidad y calidad a las normas dietéticas y de higiene"},{"ref":"Art. 308.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"a) Internos sanos. b) Internos jóvenes. c) Ración de enfermería."},{"ref":"Art. 309 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Dichos gastos se elevarán a la Junta Económico-Administrativa del Establecimiento para su examen e informe."}]},{"text":"En gestión directa, el funcionario del servicio de alimentación recibe cada día las mercancías comprobando calidad y peso, y el Médico comprueba su estado sanitario (art. 310 RP). Si un interno renuncia a su ración, queda en beneficio de los demás, no de persona determinada, sin indemnización (art. 311 RP).","refs":[{"ref":"Art. 310 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"diariamente, el funcionario del servicio de alimentación recepcionará las mercancías para la preparación de las comidas según los racionados, comprobando calidad y peso de los artículos."},{"ref":"Art. 311 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Si algún interno renunciase a su ración, quedará ésta en beneficio de los demás, no de persona determinada, sin que por tal renuncia se le deba indemnización alguna."}]}]},{"n":"7","title":"Vestuario, equipo, utensilio y lotes higiénicos","blocks":[{"text":"El interno puede vestir sus propias prendas si son adecuadas u optar por las del establecimiento (art. 20 LOGP). El centro directivo provee de vestuario, equipo y utensilios a los centros dentro de sus disponibilidades presupuestarias; la composición del vestuario se fija por resolución del centro directivo según el clima y la ubicación de los establecimientos (art. 313.1 RP). Los internos trabajadores tienen además ropa de trabajo y los niños que viven con sus madres, vestuario adecuado. La duración mínima de prendas y calzado la fija el centro directivo; para el utensilio no hay plazos mínimos y el Director pide autorización para darlo de baja (art. 314 RP).","refs":[{"ref":"Art. 313.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"La composición del vestuario se determinará por resolución del centro directivo correspondiente, teniendo en cuenta las condiciones climatológicas de las diferentes estaciones del año y las distintas tipologías y ubicaciones geográficas de los Establecimientos."},{"ref":"Art. 314.3 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"No se fijarán plazos mínimos de duración para el utensilio"}]},{"text":"Los establecimientos solicitan mensualmente los lotes higiénicos según la previsión de población, y cada mes envían inventario al centro directivo con los lotes distribuidos y los remanentes (art. 316 RP). La composición de estas dotaciones la fija cada año la Secretaría de Estado (art. 308.2 RP).","refs":[{"ref":"Art. 316.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los Establecimientos penitenciarios solicitarán mensualmente, en función de la previsión de población interna existente y de sus características personales y penitenciarias, las necesidades de dotación en lotes higiénicos."}]}]},{"n":"8","title":"Pertenencias y objetos de valor: administración y custodia","blocks":[{"text":"Salvo en régimen abierto, los internos no tienen en su poder dinero, títulos que lo representen ni objetos de valor: se les intervienen al ingresar (art. 317 RP). Los objetos de valor los custodia el Subdirector de Seguridad en la caja o en lugar seguro, y el dinero, el Administrador; el interno recibe una hoja individual de cuenta de peculio y resguardos de los objetos. Puede autorizar que se haga cargo de ellos otra persona, salvo dudas sobre su procedencia legítima. Si la autoridad judicial ordena intervenir dinero, se inmoviliza a su disposición.","refs":[{"ref":"Art. 317 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Salvo en los Establecimientos de régimen abierto, los internos no tendrán en su poder dinero o títulos que lo representen ni objetos de valor."},{"ref":"Art. 317 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los objetos de valor se custodiarán por el Subdirector de Seguridad en la caja del Establecimiento o en lugar seguro y el dinero será custodiado por el Administrador."},{"ref":"Art. 317 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"3.ª No se dará cumplimiento a lo establecido en la norma anterior cuando existan dudas acerca de la legítima procedencia del dinero u objetos de valor intervenidos"}]},{"text":"En un traslado, la Administración traslada las pertenencias del interno hasta 25 kilos; el exceso corre a su cargo, y para internos sin medios la Junta Económico-Administrativa estudia medidas que aprueba el centro directivo (art. 318 RP).","refs":[{"ref":"Art. 318.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"por un peso que nunca podrá ser superior a los 25 kilogramos, siendo con cargo al interno el traslado de todo aquel material que exceda del peso indicado."}]}]},{"n":"9","title":"El peculio: constitución y formas de gestión","blocks":[{"text":"El fondo de peculio se forma con lo que el recluso tiene al ingresar y lo que recibe después por cualquier concepto de procedencia legítima (art. 319.1 RP). Puede gestionarlo la Administración penitenciaria o entidades financieras colaboradoras mediante convenio, como cuentas bancarias individuales (art. 319.2 RP). En gestión por la Administración, cada partícipe tiene una hoja personal con los ingresos y las extracciones autorizadas semanalmente y el saldo, que concuerda con el libro general de peculio; con entidad financiera, una cartilla o similar (art. 320 RP).","refs":[{"ref":"Art. 319.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El fondo de peculio se constituirá con las cantidades que los reclusos tengan en su poder al ingresar en el Establecimiento y con las que reciban posteriormente por cualquier concepto de procedencia legítima."},{"ref":"Art. 320.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"se le inscribirán los ingresos a su nombre y las extracciones autorizadas semanalmente, con expresión del saldo"}]},{"text":"Los intereses siguen la forma de gestión (art. 324 RP): en cuentas individuales, intereses y gastos se repercuten en cada cuenta; si gestiona la Administración, los intereses de la cuenta fondo de peculio se ingresan en el Tesoro Público y se incorporan, mediante generaciones de crédito, al presupuesto penitenciario.","refs":[{"ref":"Art. 324.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"los intereses que genere la cuenta fondo de peculio se ingresarán en el Tesoro Público para su posterior incorporación, mediante generaciones de crédito"}]}]},{"n":"10","title":"Uso y transferencias del peculio","blocks":[{"text":"Con el peculio de libre disposición el interno puede atender los gastos permitidos, recibiendo una cantidad prudencial que fija el centro directivo por razones de seguridad y orden, y ordenar transferencias a su familia u otras personas con autorización previa del Administrador (art. 321 RP). Al salir en libertad se liquida su peculio y se le entrega el saldo o la cartilla, y los objetos de valor contra resguardo (art. 322.1 RP). En un traslado recibe en metálico una cantidad prudencial y el resto lo remite el Administrador del centro de origen al de destino, o se traslada la cuenta si la gestiona una entidad financiera (art. 322.2 RP). El peculio de un fallecido se entrega al primer heredero que lo solicite, contra quien pueden repetir los demás (art. 323 RP).","refs":[{"ref":"Art. 321 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"b) Ordenar transferencias a su familia o a otras personas, previa autorización del Administrador del Establecimiento."},{"ref":"Art. 322.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"En caso de traslado del interno a otro Establecimiento, se le entregará en metálico, de su peculio, una cantidad prudencial para sus gastos. El resto le será remitido por el Administrador del Establecimiento de origen al de destino"},{"ref":"Art. 323 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"El peculio de reclusos fallecidos será entregado al primer heredero del recluso que lo solicite, contra el que podrán repetir, en su caso, los restantes miembros de la comunidad hereditaria."}]}]},{"n":"R","title":"Recuerda para el examen","blocks":[{"text":"Los servicios administrativos dependen del Administrador; los actos económicos los propone el Administrador y los autoriza el Director.","refs":[{"ref":"Art. 293.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"deberá estar propuesto por el Administrador y autorizado por el Director del centro"}]},{"text":"Cuentas bancarias: firma mancomunada del Director y del Administrador o de sus suplentes.","refs":[{"ref":"Art. 294.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"la firma mancomunada del Director y del Administrador del Establecimiento o, en su caso, del suplente de uno u otro."}]},{"text":"Tres formas de gestión del economato, cocina y cafetería: Administración, organismo de trabajo (taller productivo) o empresa externa. No hay cooperativas de internos.","refs":[{"ref":"Art. 300.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los servicios de economato, de cocina y de cafetería podrán ser gestionados por:"}]},{"text":"Solo hay relación laboral especial cuando gestiona el organismo de trabajo como taller productivo.","refs":[{"ref":"Art. 305.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Cuando el economato, la cafetería o la cocina sean gestionados por el Organismo Autónomo Trabajo y Prestaciones Penitenciarias mediante la fórmula de taller productivo"}]},{"text":"En el economato nunca se venden bebidas alcohólicas ni productos farmacéuticos; el tabaco y la ropa sí.","refs":[{"ref":"Art. 303 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"b) Tabaco. c) Ropa de uso interior y exterior."}]},{"text":"Ración renunciada: para los demás, no para persona determinada, sin indemnización.","refs":[{"ref":"Art. 311 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"quedará ésta en beneficio de los demás, no de persona determinada"}]},{"text":"Lotes higiénicos: solicitud mensual. Vestuario: lo fija una resolución del centro directivo.","refs":[{"ref":"Art. 316.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los Establecimientos penitenciarios solicitarán mensualmente"}]},{"text":"Objetos de valor: Subdirector de Seguridad. Dinero: Administrador.","refs":[{"ref":"Art. 317 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"Los objetos de valor se custodiarán por el Subdirector de Seguridad"}]},{"text":"Traslado: pertenencias hasta 25 kilos a cargo de la Administración; del peculio, cantidad prudencial en metálico y el resto al centro de destino.","refs":[{"ref":"Art. 318.1 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"por un peso que nunca podrá ser superior a los 25 kilogramos"}]},{"text":"Intereses del fondo de peculio gestionado por la Administración: al Tesoro Público.","refs":[{"ref":"Art. 324.2 RP","law":"RP","url":"https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307","quote":"los intereses que genere la cuenta fondo de peculio se ingresarán en el Tesoro Público"}]}]}]'::jsonb, (select id from public.sources where url = 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307'), 'https://www.boe.es/buscar/act.php?id=BOE-A-1996-3307', null, null, null, null
  from public.topics t where t.slug = 'iipp-c20-regimen-economico-peculio'
