insert into public.sources (title, url, kind, publisher, published_on) values ('Documentos Penitenciarios 16 · La estancia en prisión: consecuencias y reincidencia (SGIP)', 'https://www.institucionpenitenciaria.es/documents/380742/72836/Documentos_Penitenciarios_16_LA_ESTANCIA_EN_PRISIxN.pdf', 'web_oficial'::public.source_kind, 'Ministerio del Interior · Secretaría General de Instituciones Penitenciarias', null) on conflict (url) do nothing;
