 where (n.outline, n.key_ideas, n.glossary, n.amendments, n.lessons)
       is distinct from (excluded.outline, excluded.key_ideas, excluded.glossary, excluded.amendments, excluded.lessons);
insert into public.sources (title, url, kind, publisher, published_on) values ('Documentos Penitenciarios 22 · Taller Convivir: 10 herramientas para vivir en comunidad (SGIP)', 'https://www.institucionpenitenciaria.es/documents/380742/72836/Documentos_Penitenciarios_22__Taller_Convivir_acc_ok_Subd.pdf', 'web_oficial'::public.source_kind, 'Ministerio del Interior · Secretaría General de Instituciones Penitenciarias', null) on conflict (url) do nothing;
